  ('597dd867-4d76-5097-82ca-fa40dacb8a19','b0b76d0f-50ca-5144-b7b7-f3c6bbb95ac6',2,'A','θ = 0°'),
  ('b197083a-4f6b-5b71-9ae3-6609ac007880','b0b76d0f-50ca-5144-b7b7-f3c6bbb95ac6',2,'B','θ = 90° (π/2)'),
  ('92dd1ab4-add7-5c51-8c23-c76b4a49cbec','b0b76d0f-50ca-5144-b7b7-f3c6bbb95ac6',2,'C','θ = 180°'),
  ('0a7328aa-8fd4-5ed1-82a8-149c434448a4','b0b76d0f-50ca-5144-b7b7-f3c6bbb95ac6',2,'D','θ = 45°'),
  ('ebb39183-ebf6-5714-82a5-d06c5f0fdfbf','dc87cd16-f11a-550a-99ad-0aa8892d4461',2,'A','F = qE'),
