  ('da817d77-50c1-59bd-b7d6-2a84cab3745d','dc87cd16-f11a-550a-99ad-0aa8892d4461',2,'D','F = pE'),
  ('df67bccd-c205-5fc2-bd16-944471512aa4','116c7534-12fb-5a3d-9eb0-b10cbe74d4da',2,'A','W = pE (sin θ₁ - sin θ₀)'),
  ('e502506e-b26a-55e1-a8db-49b56f528445','116c7534-12fb-5a3d-9eb0-b10cbe74d4da',2,'B','W = pE (cos θ₀ - cos θ₁)'),
  ('32c4fc64-f7e4-5fba-9098-2fecead28f35','116c7534-12fb-5a3d-9eb0-b10cbe74d4da',2,'C','W = pE (θ₁ - θ₀)'),
  ('7f10152c-24ff-528a-bdfe-6bcc5cd64aac','116c7534-12fb-5a3d-9eb0-b10cbe74d4da',2,'D','W = pE² (cos θ₀ - cos θ₁)'),
  ('cf684402-3f3e-5026-a0d6-4839f286c03a','df4d4a94-42c0-52ed-afd9-ad11ff5da00f',2,'A','V(r₁) - V(r₂) = E × 2a sin θ'),
  ('8e8842ed-dd74-5c33-8462-a8321757652f','df4d4a94-42c0-52ed-afd9-ad11ff5da00f',2,'B','V(r₁) - V(r₂) = -E × 2a cos θ'),
  ('33a350ca-1eec-53b1-a69e-1f8fd9016e7c','df4d4a94-42c0-52ed-afd9-ad11ff5da00f',2,'C','V(r₁) - V(r₂) = E × a cos θ'),
  ('9223ea90-76dc-5be7-86a7-14e8ae759d2c','df4d4a94-42c0-52ed-afd9-ad11ff5da00f',2,'D','V(r₁) - V(r₂) = -E × a sin θ'),
  ('e0c66624-2af2-5d05-a622-532aaa48369b','c3f8b41f-9fd5-5bf0-a6b4-28ad9d2e1ab4',2,'A','U = pE sin θ'),
