  ('45e2360c-01ec-564d-9146-80b089c19c86','5f864d64-cda6-5abd-a770-98adf3f13b05',2,'C','பூஜ்யம்'),
  ('378870b1-57cc-5c7b-80c8-8774095e5e47','5f864d64-cda6-5abd-a770-98adf3f13b05',2,'D','அவற்றுக்கு இடையே உள்ள தூரத்தைப் பொறுத்து மாறும்'),
  ('9321cbd0-704b-5044-8b88-ec848c574e03','b6d9465c-dbf9-52f2-b5e3-f174d9971de8',2,'A','எப்போதும் நேர்மறை'),
  ('9c04a883-478c-57d9-a5a0-ef098929c278','b6d9465c-dbf9-52f2-b5e3-f174d9971de8',2,'B','எப்போதும் எதிர்மறை'),
  ('6276f313-f650-568b-96f2-f7eab96c65b1','b6d9465c-dbf9-52f2-b5e3-f174d9971de8',2,'C','பூஜ்யம்'),
  ('ff99aca0-f2e1-5ba7-99d2-6cde3334c8f5','b6d9465c-dbf9-52f2-b5e3-f174d9971de8',2,'D','எந்த மின்னூட்டம் பெரியது என்பதைப் பொறுத்து மாறும்'),
  ('44ddf60c-23ca-5ff3-96c0-371efc8228e9','01e12fb9-3a52-5647-9ec2-963dd27a39d8',2,'A','அவர் மின்காந்த தூண்டலைக் கண்டுபிடித்து முதல் மின் மோட்டாரை உருவாக்கினார்'),
  ('90c06bdc-0375-53d7-b77e-ec85a3d5aeb7','01e12fb9-3a52-5647-9ec2-963dd27a39d8',2,'B','விலங்கு மின்சாரம் வேறுபட்ட உலோகங்களால் உருவாகிறது என்று நிரூபித்து, முதல் வோல்டாயிக் குவியலை (மின்கலம்) உருவாக்கினார்'),
  ('0a63cb74-ee30-532b-8945-e8dd882f6ad0','01e12fb9-3a52-5647-9ec2-963dd27a39d8',2,'C','அவர் எலக்ட்ரானைக் கண்டுபிடித்து பொருளின் அணு கோட்பாட்டை முன்மொழிந்தார்'),
  ('735cc7be-0bae-5172-9cb0-8ed4f3e22ec2','01e12fb9-3a52-5647-9ec2-963dd27a39d8',2,'D','கூலம்பின் விதியை வடிவமைத்து ஒளியின் வேகத்தை அளவிட்டார்'),
  ('68d4d2c5-6421-5f46-b929-326b26d7157f','48e658ee-ed3b-5caa-b5fa-bee5bf3c6f6d',2,'A','அந்தப் புள்ளியில் வைக்கப்பட்ட ஒரு அலகு நேர் மின்னேற்றம் அனுபவிக்கும் விசை'),
  ('e47794f3-e26a-569e-8e9d-4c44788c7782','48e658ee-ed3b-5caa-b5fa-bee5bf3c6f6d',2,'B','முடிவிலிருந்து அந்தப் புள்ளிக்கு ஒரு அலகு நேர் மின்னேற்றத்தை முடுக்கமின்றி கொண்டுவருவதற்கான வேலை'),
  ('74a2cc7a-e411-5dcc-b694-d581dae0d67c','48e658ee-ed3b-5caa-b5fa-bee5bf3c6f6d',2,'C','முடிவிலிருந்து அந்தப் புள்ளிக்கு நகரும் ஒரு மின்னேற்றம் பெறும் இயக்க ஆற்றல்'),
  ('ef8bba6b-5e5c-5395-8b07-be1a2acd4305','48e658ee-ed3b-5caa-b5fa-bee5bf3c6f6d',2,'D','மின் புலத்தில் அந்தப் புள்ளியில் உள்ள மொத்த மின்னேற்றம்'),
  ('b80cd1a6-2a7a-5e8f-bb15-95bcbeae88fc','8500aaa9-0182-59a3-90f8-dc41f7c86679',2,'A','இரண்டு புள்ளிகளுக்கு இடையே சேமிக்கப்பட்ட மொத்த மின்னேற்றம்'),
  ('20c27fe0-97d5-54f8-847a-b7b92fc29591','8500aaa9-0182-59a3-90f8-dc41f7c86679',2,'B','இரண்டு புள்ளிகளுக்கு இடையே ஒரு மின்னேற்றத்தை நகர்த்துவதற்கான ஒரு அலகு மின்னேற்றத்திற்கான வேலை'),
  ('bfc6f2c6-9e16-50b4-826f-4523554825d5','8500aaa9-0182-59a3-90f8-dc41f7c86679',2,'C','இரண்டு புள்ளிகளுக்கு இடையேயான மையப்புள்ளியில் உள்ள மின் புலத்தின் வலிமை'),
  ('778ef38a-a6a9-5fe9-b867-7342b2aee278','8500aaa9-0182-59a3-90f8-dc41f7c86679',2,'D','இரண்டு புள்ளிகளுக்கு இடையேயான தூரம் மீட்டர்களில்'),
  ('17ac208c-aee5-51f9-90ea-44b183636df5','5a0881c6-6658-52dc-8486-2b94444affcc',2,'A','முடிவில் மட்டுமே மின் புலம் பூஜ்ஜியமாக இருப்பதால்'),
  ('7e00b4d5-6290-5a8e-a994-7f2dc8951128','5a0881c6-6658-52dc-8486-2b94444affcc',2,'B','திறன் ஆற்றல் ஒரு கூட்டல் மாறிலிக்குள் வரையறுக்கப்படாதது, முடிவு ஒரு வசதியான குறிப்பை வழங்குகிறது'),
  ('8a862fc6-37ce-58a6-b81a-72068c798407','5a0881c6-6658-52dc-8486-2b94444affcc',2,'C','எல்லா மின்னேற்றங்களும் முடிவில் இருப்பதால்'),
  ('cb94a189-9bd3-5aea-bf0d-9052e504b587','5a0881c6-6658-52dc-8486-2b94444affcc',2,'D','அந்தப் புள்ளியில் ஒளியின் வேகம் முடிவற்றது என்பதால்'),
  ('bb5c633a-9146-53cb-8722-52d813c0f015','5a5c0588-a69a-55db-ac2c-0db81e969e9b',2,'A','அது வெப்ப ஆற்றலாக மாற்றப்பட்டு சுற்றுப்புறத்திற்கு இழக்கப்படுகிறது'),
  ('c365a59d-d167-5de7-8f36-8acf9c40c1c6','5a5c0588-a69a-55db-ac2c-0db81e969e9b',2,'B','அது முழுமையாக q-ன் திறன் ஆற்றலாக சேமிக்கப்படுகிறது'),
  ('230554dd-d4c7-5502-b3d1-f6a75989f669','5a5c0588-a69a-55db-ac2c-0db81e969e9b',2,'C','அது உடனடியாக q-ன் இயக்க ஆற்றலை அதிகரிக்கப் பயன்படுத்தப்படுகிறது'),
  ('25439ad7-4368-5496-8c9d-8270860317b4','5a5c0588-a69a-55db-ac2c-0db81e969e9b',2,'D','அது மூல மின்னேற்றம் Q-க்கு மாற்றப்படுகிறது'),
  ('f4135b85-d8fe-59c8-986c-6e9ed473b90d','de865708-19e2-5dec-aefe-72704ec65041',2,'A','செய்யப்பட்ட வேலை இரண்டு புள்ளிகளுக்கு இடையே எடுக்கப்பட்ட பாதையைச் சார்ந்தது'),
  ('a8c73f8b-21e5-5b1c-a7ed-e547a9aa6337','de865708-19e2-5dec-aefe-72704ec65041',2,'B','செய்யப்பட்ட வேலை தொடக்க மற்றும் இறுதி நிலைகளை மட்டுமே சார்ந்தது, பாதையைச் சார்ந்ததல்ல'),
  ('5990f767-918a-5998-bb3b-bc8f7676f5cf','de865708-19e2-5dec-aefe-72704ec65041',2,'C','எந்தவொரு பாதையிலும் செய்யப்பட்ட வேலை எப்போதும் பூஜ்ஜியம்'),
  ('e7f70548-2cf9-5f83-8ad4-76a95375e42d','de865708-19e2-5dec-aefe-72704ec65041',2,'D','எந்தவொரு மூடிய பாதைக்கும் செய்யப்பட்ட வேலை முடிவற்றது'),
  ('d904c624-e7b9-5ab0-8503-47cfd0915442','efc4e451-6af5-5d5d-bdb9-720b6d74e441',2,'A','தவளை தசை திசுக்கள் சிறப்பு காந்த பண்புகளைக் கொண்டிருக்கின்றன'),
  ('1f972f4e-43b5-5a00-adb9-625ba9ab4cfe','efc4e451-6af5-5d5d-bdb9-720b6d74e441',2,'B','விலங்கு மின்சாரம் விலங்கு திசுக்களின் சிறப்பு பண்புகளால் ஏற்படுகிறது'),
  ('1493a5cd-d41c-568b-ae8e-dcf9fdb23ecb','efc4e451-6af5-5d5d-bdb9-720b6d74e441',2,'C','மின்சாரம் வேறுபட்ட உலோகங்களாலும் ஈரமான பொருட்களாலும் உருவாகிறது, சிறப்பு விலங்கு பண்புகளால் அல்ல'),
  ('98fa16b2-7559-5b56-b286-6d9efb51a872','efc4e451-6af5-5d5d-bdb9-720b6d74e441',2,'D','தவளை தசைகள் தனித்து வேதியியல் வினைகள் மூலம் மின்சாரத்தை உருவாக்குகின்றன'),
  ('d3c78fef-beb7-53e0-acc1-e79ceecc7d2c','1b3fb128-3632-5b96-b1c5-c56903f21817',2,'A','செய்யப்பட்ட வேலை q-க்கு எதிர்விகிதத்தில் இருப்பதால்'),
  ('10d9e814-d30e-55c3-8443-ae7ed6045458','1b3fb128-3632-5b96-b1c5-c56903f21817',2,'B','செய்யப்பட்ட வேலை q-க்கு நேர்விகிதத்தில் உள்ளது, q-ஆல் வகுப்பதால் சோதனை மின்னேற்றத்திலிருந்து சுதந்திரமானது'),
  ('e0f3bf61-3aab-532e-937c-987567d30077','1b3fb128-3632-5b96-b1c5-c56903f21817',2,'C','மின்னேற்றம் q எப்போதும் 1 கூலும் ஆக இருப்பதால்'),
  ('c3de6eb8-46f1-5f46-95c1-212a3d2bbcc0','1b3fb128-3632-5b96-b1c5-c56903f21817',2,'D','q-ஆல் வகுப்பதால் வேலை விசையாக மாற்றப்படுகிறது')
INSERT INTO questions (id, language, standard, subject, chapter_id, chapter_label, "correct", correct_option, question, options, explanation, question_tag, status) VALUES
  ('34e4dfb9-1c74-54c1-957f-d67918802243','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்கடத்தாப் பொருட்களின் அடிப்படைப் பண்பு என்ன?','["கடத்திகளை விட அதிக இலவச மின்னேற்றத் துகள்களைக் கொண்டிருக்கும்", "இலவச மின்னேற்றத் துகள்களைக் கொண்டிருக்காது அல்லது மிகக் குறைந்த அளவே கொண்டிருக்கும்", "அவற்றின் உள்ளே மின்புலம் எப்போதும் பூஜ்யமாக இருக்கும்", "வெளிப்புலத்தால் முனைவாக்க முடியாது"]'::jsonb,'Dielectrics are non-conducting substances that have no or negligible number of charge carriers, unlike conductors which have free electrons. | மின்கடத்தாப் பொருட்கள் கடத்திகளைப் போலல்லாமல், இலவச மின்னேற்றம் கொண்ட துகள்களைக் கொண்டிருக்காது அல்லது மிகக் குறைந்த அளவே கொண்டிருக்கும்.','TAPHY12TA02Q0242','active'),
  ('f4e42f16-25db-578f-b6bb-1905f414a39c','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','வெளிப்புலத்தில் வைக்கப்படும்போது, கடத்தியின் உள்ளே நிலையான நிலையில் மின்புலம் எவ்வாறு இருக்கும்?','["வெளிப்புலத்திற்குச் சமமாக இருக்கும்", "வெளிப்புலத்தின் பாதியாக இருக்கும்", "பூஜ்யமாக இருக்கும்", "வெளிப்புலத்தின் இருமடங்காக இருக்கும்"]'::jsonb,'In a conductor, free charge carriers move until the induced field exactly cancels the external field, making the net electrostatic field zero inside. | கடத்தியின் உள்ளே மின்னியல் புலம் பூஜ்யமாகிறது, ஏனெனில் இலவச மின்னேற்றத் துகள்கள் நகர்ந்து மீள்புலத்தை உருவாக்கி வெளிப்புலத்தை முற்றிலும் நீக்குகின்றன.','TAPHY12TA02Q0243','active'),
  ('444385f3-a415-5377-bd05-779473fd0965','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்கடத்தாப் பொருளில் மறைவுறு புலம் வெளிப்புலத்துடன் ஒப்பிடும்போது எவ்வாறு இருக்கும்?','["வெளிப்புலத்தை முற்றிலும் நீக்கும்", "வெளிப்புலத்தைக் குறைக்கும் ஆனால் முற்றிலும் நீக்காது", "வெளிப்புலத்தை அதிகரிக்கும்", "வெளிப்புலத்தில் எந்த விளைவும் ஏற்படுத்தாது"]'::jsonb,'Unlike conductors, dielectrics cannot completely cancel the external field. The induced field only reduces the external field because free movement of charges is not possible in dielectrics. | கடத்திகளைப் போலல்லாமல், மின்கடத்தாப் பொருட்களில் மின்னேற்ற நகர்வு சாத்தியமற்றதால், மீள்புலம் வெளிப்புலத்தை முழுவதுமாக நீக்காமல் குறைக்கிறது.','TAPHY12TA02Q0244','active'),
  ('984bd096-e11f-5a38-a1c2-46add7153e7d','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','முனைவாய் மூலக்கூறுகள் பற்றிய சரியான கூற்று எது?','["அவற்றில் நிரந்தர இருமுனைத் திருப்புத்திறன் உள்ளது", "நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருக்கும்", "அவை எப்போதும் வெளிப்புலத்துடன் சீரமைக்கும்", "அவற்றை முனைவாக்க முடியாது"]'::jsonb,'In non-polar molecules, the centres of positive and negative charges coincide, so they have no permanent dipole moment. Examples include O₂ and H₂. | முனைவாய்ப் பொருட்களில் நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருப்பதால், நிரந்தர இருமுனைத் திருப்புத்திறன் இருக்காது. எடுத்துக்காட்டுகள்: O₂, H₂.','TAPHY12TA02Q0245','active'),
  ('0961ad5d-45c4-5699-8b10-d4fa0e6da336','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','பின்வருவனவற்றில் எவை முனைவாய் மூலக்கூறுகளுக்கான எடுத்துக்காட்டுகள்?','["HCl மற்றும் H₂O", "O₂ மற்றும் H₂", "NaCl மற்றும் HCl", "NH₃ மற்றும் H₂O"]'::jsonb,'Oxygen (O₂) and hydrogen (H₂) are non-polar molecules because their symmetry causes the centres of positive and negative charges to coincide. | ஆக்ஸிஜன் (O₂) மற்றும் ஹைட்ரஜன் (H₂) முனைவாய் மூலக்கூறுகள் ஆகும், ஏனெனில் அவற்றின் சமச்சீர் காரணமாக நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருக்கும்.','TAPHY12TA02Q0246','active'),
  ('0b724734-7293-5a3a-ac8a-76e5ae26b161','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','முனைவுறு மூலக்கூறின் சிறப்பியல்பு என்ன?','["நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் எப்போதும் ஒன்றாக இருக்கும்", "வெளிப்புலத்திலும் நிரந்தர இருமுனைத் திருப்புத்திறன் இல்லாமல் இருக்கும்", "வெளிப்புலம் இல்லாதபோதும் நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் பிரிந்திருக்கும்", "அவற்றில் மறைவுறு இருமுனைத் திருப்புத்திறனை உருவாக்க முடியாது"]'::jsonb,'Polar molecules have permanent dipole moments because the centres of positive and negative charges are separated even without an external field. Examples include HCl and H₂O. | முனைவுறு மூலக்கூறுகளில் வெளிப்புலம் இல்லாதபோதும் நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் பிரிந்திருக்கும், எனவே நிரந்தர இருமுனைத் திருப்புத்திறன் கொண்டவை. எடுத்துக்காட்டுகள்: HCl, H₂O.','TAPHY12TA02Q0247','active'),
  ('f3cbc90f-dd83-5949-b126-7f40657bc26e','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','உரையில் கொடுக்கப்பட்டுள்ள முனைவுறு மூலக்கூறுகளின் எடுத்துக்காட்டுகள் எவை?','["O₂ மற்றும் CO₂", "H₂ மற்றும் N₂", "HCl மற்றும் H₂O", "CH₄ மற்றும் C₂H₆"]'::jsonb,'HCl (hydrogen chloride) and H₂O (water) are examples of polar molecules because they have permanent dipole moments due to charge separation. | HCl (ஹைட்ரஜன் குளோரைடு) மற்றும் H₂O (நீர்) ஆகியவை முனைவுறு மூலக்கூறுகளுக்கான எடுத்துக்காட்டுகள், ஏனெனில் அவற்றில் மின்னேற்றப் பிரிவினையால் நிரந்தர இருமுனைத் திருப்புத்திறன் உள்ளது.','TAPHY12TA02Q0248','active'),
  ('c8327d53-328b-595a-afa8-38acd6768c55','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','முனைவாய் மூலக்கூறுகள் வெளிப்புலத்தில் இருமுனைத் திருப்புத்திறனை எவ்வாறு பெறுகின்றன?','["பொருள் முழுவதும் எலக்ட்ரான்களின் இலவச நகர்வு மூலம்", "மூலக்கூறுகளை நீட்டுவதன் அல்லது மீண்டும் சீரமைப்பதன் மூலம், மின்னேற்ற இடப்பெயர்ச்சி ஏற்படுத்துவதால்", "மூலக்கூறுகளின் முழு அயனியாக்கத்தால்", "மின்னேற்றங்களின் வெப்பச் சலனத்தால்"]'::jsonb,'In non-polar molecules, the positive and negative charges are displaced in opposite directions under an external field, creating an induced dipole moment until balanced by internal restoring forces. | முனைவாய் மூலக்கூறுகளில், வெளிப்புலத்தின் கீழ் நேர் மற்றும் எதிர் மின்னேற்றங்கள் எதிர் திசைகளில் இடப்பெயர்ச்சி அடைந்து, மீள்திருப்பு விசைகளால் சமநிலையடையும் வரை மறைவுறு இருமுனைத் திருப்புத்திறனை உருவாக்குகின்றன.','TAPHY12TA02Q0249','active'),
  ('28834f2f-c9d6-5751-b333-bb6c37441436','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','வெளிப்புலம் இல்லாதபோது, முனைவுறு மூலக்கூறுகளின் மொத்த இருமுனைத் திருப்புத்திறன் என்ன?','["அதிகபட்சமாக ஒரு திசையில் சீரமைந்திருக்கும்", "வெப்பச் சலனத்தால் சீரற்ற திசைகளில் அமைந்திருப்பதால் பூஜ்யமாக இருக்கும்", "சாத்தியமான அதிகபட்ச மதிப்பின் பாதியாக இருக்கும்", "மின்கடத்தா மாறிலியைப் பொறுத்து இருக்கும்"]'::jsonb,'Without an external field, permanent dipoles of polar molecules are randomly oriented due to thermal agitation, making the total dipole moment zero. | வெளிப்புலம் இல்லாதபோது, வெப்பச் சலனத்தால் நிரந்தர இருமுனைகள் சீரற்ற திசைகளில் அமைந்திருப்பதால், மொத்த இருமுனைத் திருப்புத்திறன் பூஜ்யமாக இருக்கும்.','TAPHY12TA02Q0250','active'),
  ('81a69563-c645-56ef-a007-71cc943240ca','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்கடத்தாப் பொருளில் முனைவாக்கம் P என்றால் என்ன?','["மின்கடத்தாப் பொருளின் மேற்பரப்பில் உள்ள மொத்த மின்னேற்றம்", "மின்கடத்தாப் பொருளின் உள்ளே மின்புலத்தின் வலிமை", "அலகு பருமனுக்கான இருமுனைத் திருப்புத்திறன்", "மின்கடத்தாப் பொருளின் குறுக்கே உள்ள மின்னழுத்த வேறுபாடு"]'::jsonb,'Polarisation P is defined as the dipole moment per unit volume. For linear isotropic dielectrics, P = χₑε₀E, where χₑ is the electric susceptibility. | மின்கடத்தாப் பொருளில் முனைவாக்கம் P என்பது அலகு பருமனுக்கான இருமுனைத் திருப்புத்திறன். நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களுக்கு P = χₑε₀E.','TAPHY12TA02Q0251','active'),
  ('9677f62a-a63c-5bb1-abc2-93e8a7022e92','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','P = χₑε₀E சமன்பாட்டில் χ₎ என்ற குறியீடு எதைக் குறிக்கிறது?','["மின்கடத்தா மாறிலியை", "மின்கடத்தா ஊடகத்தின் மின் உணர்திறனை", "வெற்றிடத்தின் மின் உடைப்புத்திறனை", "மறைவுறு மேற்பரப்பு மின்னேற்ற அடர்த்தியை"]'::jsonb,'χₑ is called the electric susceptibility, a constant characteristic of the dielectric that describes how easily the material can be polarised. | χₑ என்பது மின் உணர்திறன், இது மின்கடத்தாப் பொருளின் பண்பாகும். இது அப்பொருள் எளிதாக முனைவாக்கப்படும் தன்மையைக் குறிக்கிறது.','TAPHY12TA02Q0252','active'),
  ('29c929de-dca5-5942-8752-ada4df3f8538','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களில் மறைவுறு இருமுனைத் திருப்புத்திறன் பற்றிய கருதுகோள் என்ன?','["அது புலத்திற்கு எதிர் திசையிலும் புல வலிமைக்கு நேர்விகிதத்திலும் இருக்கும்", "அது புலத்தின் திசையிலும் புல வலிமைக்கு நேர்விகிதத்திலும் இருக்கும்", "அது புல வலிமையிலிருந்து சுதந்திரமாக இருக்கும்", "அது எப்போதும் புலத் திசைக்கு செங்குத்தாக இருக்கும்"]'::jsonb,'For linear isotropic dielectrics, the induced dipole moment is assumed to be in the direction of the field and proportional to the field strength. | நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களுக்கு, மறைவுறு இருமுனைத் திருப்புத்திறன் புலத்தின் திசையிலும் புல வலிமைக்கு நேர்விகிதத்திலும் இருக்கும்.','TAPHY12TA02Q0253','active'),
  ('14109a2e-5841-50d3-9cbe-cdeacd35b2b1','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','முனைவுறு மூலக்கூறுகளில் முனைவாக்கத்தின் அளவை எந்த இரண்டு காரணிகள் தீர்மானிக்கின்றன?','["மின்கடத்தாப் பொருளின் நிறை மற்றும் வெப்பநிலை", "இருமுனைத் திறன் ஆற்றல் புலத்துடன் சீரமைக்கவும், வெப்ப ஆற்றல் சீரமைப்பைக் குலைக்கவும்", "மின்கடத்தாப் பொருளின் அழுத்தம் மற்றும் பருமன்", "மின்புல அதிர்வெண் மற்றும் அலைநீளம்"]'::jsonb,'The extent of polarisation depends on the competition between dipole potential energy (which tends to align dipoles with the field) and thermal energy (which tends to disrupt alignment). | முனைவாக்கத்தின் அளவு இருமுனைத் திறன் ஆற்றல் (புலத்துடன் சீரமைக்கும்) மற்றும் வெப்ப ஆற்றல் (சீரமைப்பைக் குலைக்கும்) ஆகிய இரண்டுக்கும் இடையேயான போட்டியைப் பொறுத்தது.','TAPHY12TA02Q0254','active'),
  ('0a5cdd19-f7f9-519b-afa9-c11912a1fd27','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','உரையின் படம் 2.21-இன்படி CO₂ எவ்வாறு வகைப்படுத்தப்பட்டுள்ளது?','["முனைவுறு மூலக்கூறாக", "முனைவாய் மூலக்கூறாக", "அயனிச் சேர்மமாக", "கடத்தியாக"]'::jsonb,'CO₂ is shown in Figure 2.21 as a non-polar molecule because of its linear symmetry, causing the centres of positive and negative charges to coincide. | CO₂ படம் 2.21-ல் முனைவாய் மூலக்கூறாகக் காட்டப்பட்டுள்ளது, ஏனெனில் அதன் நேர்கோட்டு சமச்சீர் காரணமாக நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருக்கும்.','TAPHY12TA02Q0255','active'),
  ('8bd09c8b-749a-5068-991f-726c472aa0ff','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','முனைவாக்கப்பட்ட மின்கடத்தாப் பொருளின் மேற்பரப்பில் எந்த வகை மின்னேற்றங்கள் தோன்றுகின்றன?','["பொருள் முழுவதும் நகரக்கூடிய இலவச மின்னேற்றங்கள்", "மூலக்கூறுகளில் கட்டப்பட்ட மறைவுறு மேற்பரப்பு மின்னேற்றங்கள்", "இரு மேற்பரப்புகளிலும் நேர் மின்னேற்றங்கள் மட்டுமே", "இரு மேற்பரப்புகளிலும் எதிர் மின்னேற்றங்கள் மட்டுமே"]'::jsonb,'The collective effect of molecular dipole moments produces net charges on the surface of the dielectric. These are induced charges that are bound to the molecules, not free charges. | மூலக்கூறு இருமுனைகளின் கூட்டு விளைவாக மின்கடத்தாப் பொருளின் மேற்பரப்பில் மறைவுறு மின்னேற்றங்கள் தோன்றுகின்றன. இவை மூலக்கூறுகளில் கட்டப்பட்டவை, இலவச மின்னேற்றங்கள் அல்ல.','TAPHY12TA02Q0256','active'),
  ('465edb8f-1dab-5071-8063-63279eeaf61f','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','வெளிப்புலம் இல்லாதபோது, வெப்பச் சலனம் முனைவுறு மூலக்கூறுகளில் என்ன விளைவை ஏற்படுத்துகிறது?','["அனைத்து இருமுனைகளையும் ஒரு திசையில் சீரமைக்கிறது", "இருமுனைகளை சீரற்ற திசைகளில் சுழற்றுவதால் மொத்த இருமுனைத் திருப்புத்திறன் பூஜ்யமாகிறது", "நிரந்தர இருமுனைகளை அழிக்கிறது", "மின்கடத்தா மாறிலியை அதிகரிக்கிறது"]'::jsonb,'Thermal agitation causes random orientation of permanent dipoles, so the total dipole moment averages to zero when no external field is applied. | வெப்பச் சலனம் நிரந்தர இருமுனைகளை சீரற்ற திசைகளில் சுழற்றுவதால், வெளிப்புலம் இல்லாதபோது மொத்த இருமுனைத் திருப்புத்திறன் பூஜ்யமாகிறது.','TAPHY12TA02Q0257','active'),
  ('41a7bbc8-39f1-5cc5-85ad-9ae737ed46a5','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','வெளிப்புலத்தின் கீழ் முனைவாய் மூலக்கூறில் மின்னேற்ற இடப்பெயர்ச்சி எப்போது நிற்கிறது?','["வெளிப்புலம் பூஜ்யமாகும்போது", "வெளிப்புல விசை உள் மீள்திருப்பு விசையால் சமநிலையடையும்போது", "மூலக்கூறு முழுவதுமாக அயனியாக்கப்படும்போது", "வெப்பநிலை தனிமப்பூஜ்யத்தை அடையும்போது"]'::jsonb,'The displacement stops when the external force on constituent charges is balanced by the restoring force due to internal fields in the molecule. | வெளிப்புலத்தால் ஏற்படும் விசை, மூலக்கூறின் உள் புலங்களால் ஏற்படும் மீள்திருப்பு விசையால் சமநிலையடையும்போது மின்னேற்ற இடப்பெயர்ச்சி நிற்கிறது.','TAPHY12TA02Q0258','active'),
  ('367a2542-3d9f-57f9-a2f8-f2ddbbe15175','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களுக்கு, முனைவாக்கம் P, மின்புலம் E, மற்றும் மின் உணர்திறன் χₑ ஆகியவற்றை சரியாக இணைக்கும் சமன்பாடு எது?','["P = χₑ / E", "P = χₑε₀E", "P = E / χₑ", "P = χₑ + ε₀E"]'::jsonb,'The correct equation is P = χₑε₀E, where ε₀ is the permittivity of free space and χₑ is the electric susceptibility. | சரியான சமன்பாடு P = χₑε₀E, இதில் ε₀ வெற்றிடத்தின் மின் உடைப்புத்திறன், χₑ மின் உணர்திறன்.','TAPHY12TA02Q0259','active'),
  ('6db00b85-35dc-5603-aca7-e1c792dc2f90','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','வெளிப்புலத்தில் வைக்கப்படும்போது கடத்தி மற்றும் மின்கடத்தாப் பொருளுக்கு இடையே உள்ள முக்கிய வேறுபாடு என்ன?','["இரண்டும் உள்ளே வெளிப்புலத்தை முற்றிலும் நீக்குகின்றன", "கடத்திகள் புலத்தை முழுவதுமாக நீக்குகின்றன; மின்கடத்தாப் பொருட்கள் அதைக் குறைக்கின்றன", "மின்கடத்தாப் பொருட்கள் புலத்தை முழுவதுமாக நீக்குகின்றன; கடத்திகள் அதைக் குறைக்கின்றன", "இரண்டும் வெளிப்புலத்தில் எந்த விளைவையும் ஏற்படுத்துவதில்லை"]'::jsonb,'Conductors have free charges that move to completely cancel the external field inside. Dielectrics lack free charge carriers, so they can only reduce the field through polarisation. | கடத்திகளில் இலவச மின்னேற்றங்கள் நகர்ந்து வெளிப்புலத்தை முழுவதுமாக நீக்குகின்றன. மின்கடத்தாப் பொருட்களில் இலவச மின்னேற்றங்கள் இல்லாததால், முனைவாக்கம் மூலம் புலத்தை மட்டுமே குறைக்க முடியும்.','TAPHY12TA02Q0260','active'),
  ('a4d969f1-cce5-5e5e-9d82-7fa8ad43ba53','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்கடத்தாப் பொருளில் முனைவாக்கத்தின் அளவு பின்வருவனவற்றில் எதைப் பொறுத்தது?','["வெளிப்புலத்தின் வலிமை மட்டுமே", "மின்கடத்தாப் பொருளின் வெப்பநிலை மட்டுமே", "மின்கடத்தாப் பொருளின் தன்மை", "மின்கடத்தாச் சட்டத்தின் தடிமன் மட்டுமே"]'::jsonb,'The text states that the extent of the effect depends on the nature of the dielectric, which includes molecular properties like whether molecules are polar or non-polar. | மின்கடத்தாப் பொருளின் தன்மை, அதாவது மூலக்கூறுகள் முனைவுறு அல்லது முனைவாய் என்பது போன்ற பண்புகள், முனைவாக்கத்தின் அளவைத் தீர்மானிக்கின்றன.','TAPHY12TA02Q0261','active'),
  ('6b543a19-7a7a-5fce-8a06-6ad91fcba1a8','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு புள்ளி மின்னேற்றம் Q ஆதிப்புள்ளியில் வைக்கப்பட்டுள்ளது. r தூரத்தில் உள்ள P புள்ளியில் மின்னிலை V இன் வெளிப்பாடு என்ன?','["V = Q / (4πε₀r²)", "V = Q / (4πε₀r)", "V = Qr / (4πε₀)", "V = Qε₀ / (4πr)"]'::jsonb,'The electrostatic potential due to a point charge Q at distance r is V = Q/(4πε₀r). This is derived by calculating work done in bringing a unit positive test charge from infinity to point P. | புள்ளி மின்னேற்றம் Q இன் காரணமாக r தூரத்தில் மின்னிலை V = Q/(4πε₀r) என வருகிறது. இது முடிவிலிருந்து P புள்ளிக்கு ஒரு அலகு நேர்மின்னேற்றத்தைக் கொண்டுவருவதற்கான வேலையைக் கணக்கிடுவதால் கிடைக்கிறது.','TAPHY12TA02Q0262','active'),
  ('6ded962d-959f-5f38-8c8d-99edda809446','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','Q = 4 × 10⁻⁷ C என்ற புள்ளி மின்னேற்றம் 9 cm தூரத்தில் உள்ள P புள்ளியில் மின்னிலை என்ன?','["2 × 10⁴ V", "4 × 10⁴ V", "6 × 10⁴ V", "8 × 10⁴ V"]'::jsonb,'Using V = (1/4πε₀)(Q/r) with Q = 4×10⁻⁷ C and r = 9×10⁻² m, we get V = 9×10⁹ × (4×10⁻⁷)/(9×10⁻²) = 4×10⁴ V. This matches Example 2.1(a). | V = (1/4πε₀)(Q/r) சூத்திரத்தைப் பயன்படுத்தி, Q = 4×10⁻⁷ C, r = 9×10⁻² m என்பதைக் கொண்டு, V = 9×10⁹ × (4×10⁻⁷)/(9×10⁻²) = 4×10⁴ V கிடைக்கிறது.','TAPHY12TA02Q0263','active'),
  ('d31a9e89-8f10-5fd9-8c83-474d9542f28d','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்னிலை 4 × 10⁴ V உள்ள P புள்ளிக்கு q = 2 × 10⁻⁹ C ஐ முடிவிலிருந்து கொண்டுவர செய்யப்படும் வேலை என்ன?','["4 × 10⁻⁵ J", "6 × 10⁻⁵ J", "8 × 10⁻⁵ J", "10 × 10⁻⁵ J"]'::jsonb,'Work done W = qV. Substituting q = 2×10⁻⁹ C and V = 4×10⁴ V, we get W = 2×10⁻⁹ × 4×10⁴ = 8×10⁻⁵ J. This is Example 2.1(b). | செய்யப்பட்ட வேலை W = qV. q = 2×10⁻⁹ C மற்றும் V = 4×10⁴ V ஆகியவற்றைப் பதிலிட, W = 2×10⁻⁹ × 4×10⁴ = 8×10⁻⁵ J கிடைக்கிறது.','TAPHY12TA02Q0264','active'),
  ('83fe6775-4c51-5e41-9c13-c0ef50c8b94e','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','எதிர்மறை புள்ளி மின்னேற்றம் Q < 0 இருக்கும்போது, எந்தவொரு புள்ளியிலும் மின்னிலை V இன் குறி என்ன?','["நேர்மறை", "எதிர்மறை", "பூஜ்யம்", "தூரத்தைப் பொறுத்தது"]'::jsonb,'For Q < 0, V = Q/(4πε₀r) is negative since r is always positive. Work done by external force is negative. | Q < 0 எனில், V = Q/(4πε₀r) என்பது எப்போதும் எதிர்மறையாக இருக்கும், ஏனெனில் r எப்போதும் நேர்மறை. வெளிப்புற விசையால் செய்யப்படும் வேலை எதிர்மறையாக இருக்கும்.','TAPHY12TA02Q0265','active'),
  ('e1fedc89-00dc-5aa1-971f-2d9fef9bd825','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு புள்ளி மின்னேற்றத்தின் காரணமாக மின்னிலை தூரம் r உடன் எவ்வாறு மாறுகிறது?','["1/r²", "1/r", "r", "r²"]'::jsonb,'V = Q/(4πε₀r) shows V ∝ 1/r. Electric field E ∝ 1/r². Figure 2.4 illustrates this. | V = Q/(4πε₀r) என்பதால், V ∝ 1/r என மாறுகிறது. மின்புலம் E ∝ 1/r² என்பதற்கு மாறாக இது உள்ளது.','TAPHY12TA02Q0266','active'),
  ('d788cada-d659-5d08-9bb8-d24ed3faa772','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','முடிவிலிருந்து ஒரு புள்ளிக்கு மின்னேற்றத்தைக் கொண்டுவருவதற்கான வேலை பாதையைப் பொறுத்ததா?','["ஆம், பாதையைப் பொறுத்தது", "இல்லை, பாதையைப் பொறுத்தது அல்ல", "நேர்க்கோடு பாதைகளுக்கு மட்டுமே", "ஆர வரிசை பாதைகளுக்கு மட்டுமே"]'::jsonb,'Work done is path-independent because electrostatic force is conservative. We choose a convenient radial path for calculation. | மின்னிலைக்கு எதிராக செய்யப்படும் வேலை பாதையைப் பொறுத்தது அல்ல, ஏனெனில் மின்னச்சு விசை ஒரு பாதுகாப்பு விசை. எந்த பாதையிலும் முடிவு ஒன்றே.','TAPHY12TA02Q0267','active'),
  ('60a762cd-cb8c-508c-9fbb-1d20b3909f72','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஆதிப்புள்ளியிலிருந்து r'' தூரத்தில் உள்ள P'' புள்ளியில், Q மின்னேற்றத்தின் காரணமாக ஒரு அலகு நேர்மின்னேற்றத்திற்கான மின்னச்சு விசை என்ன?','["(1/4πε₀)(Q/r'') r̂", "(1/4πε₀)(Q/r''²) r̂", "(1/4πε₀)(Q²/r'') r̂", "(1/4πε₀)(Q/r''³) r̂"]'::jsonb,'By Coulomb''s law, F = (1/4πε₀)(Q/r''²) r̂, where r̂ is unit vector along OP''. This is Eq. (2.5). | Q இன் காரணமாக r'' தூரத்தில் ஒரு அலகு நேர்மின்னேற்றத்திற்கான மின்னச்சு விசை கூலம்பின் விதிப்படி F = (1/4πε₀)(Q/r''²) r̂ என அமையும்.','TAPHY12TA02Q0268','active'),
  ('3c39c962-cc5d-5889-9712-dee3a9a64f4f','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','r'' இலிருந்து r'' + Δr'' க்கு ஒரு அலகு மின்னேற்றத்தை நகர்த்துவதற்கான வேலை ΔW இன் வெளிப்பாடு என்ன?','["ΔW = (Q/4πε₀r''²) Δr''", "ΔW = -(Q/4πε₀r''²) Δr''", "ΔW = (Q/4πε₀r'') Δr''", "ΔW = -(Q/4πε₀r'') Δr''"]'::jsonb,'ΔW = -(Q/4πε₀r''²) Δr''. Negative sign ensures ΔW is positive when Δr'' < 0 (moving inward). This is Eq. (2.6). | மின்னச்சு விசைக்கு எதிராக நகர்த்தும்போது செய்யப்படும் வேலை ΔW = -(Q/4πε₀r''²) Δr''. எதிர்மறைக் குறி Δr'' < 0 எனில் ΔW நேர்மறையாக இருக்க வேண்டும் என்பதற்காக.','TAPHY12TA02Q0269','active'),
  ('afdceb8f-47b7-540c-a5eb-bead23b5f18f','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','Q இலிருந்து r தூரத்திற்கு ஒரு அலகு மின்னேற்றத்தைக் கொண்டுவருவதற்கான மொத்த வேலையைக் கணக்கிட ஒருங்கிணைக்கும் வரம்புகள் எவை?','["r இலிருந்து முடிவு வரை", "0 இலிருந்து r வரை", "முடிவிலிருந்து r வரை", "r இலிருந்து 0 வரை"]'::jsonb,'Integration from r'' = ∞ to r'' = r gives W = Q/(4πε₀r). This is Eq. (2.7) on the page. | r'' = ∞ இலிருந்து r'' = r வரை ஒருங்கிணைக்கப்படுகிறது. முடிவு W = Q/(4πε₀r).','TAPHY12TA02Q0270','active'),
  ('72babb03-630e-56e3-acb1-a594cbb2f8c4','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','முடிவில் மின்னிலை பூஜ்யம் எனத் தேர்ந்தெடுத்தால், Q மின்னேற்றத்தின் காரணமாக P புள்ளியில் மின்னிலை என்ன?','["P இலிருந்து முடிவுக்கு மின்புலத்தால் செய்யப்படும் வேலை", "முடிவிலிருந்து P க்கு வெளிப்புற விசையால் செய்யப்படும் வேலை", "முடிவிலிருந்து P க்கு மின்புலத்தால் செய்யப்படும் வேலை", "P இலிருந்து முடிவுக்கு வெளிப்புற விசையால் செய்யப்படும் வேலை"]'::jsonb,'With V(∞) = 0, potential at P equals work done by external force in bringing unit positive charge from infinity to P. This is the definition on the page. | V(∞) = 0 எனத் தேர்ந்தெடுக்கும்போது, P இல் மின்னிலை முடிவிலிருந்து P க்கு ஒரு அலகு நேர்மின்னேற்றத்தைக் கொண்டுவருவதற்கான வெளிப்புற விசையின் வேலையாகும்.','TAPHY12TA02Q0271','active'),
  ('be5701ed-c54b-5d8d-a35b-d952ac03a652','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','Q > 0 எனில், முடிவிலிருந்து P புள்ளிக்கு ஒரு அலகு நேர்மின்னேற்றத்தைக் கொண்டுவருவதற்கு விரட்டும் விசைக்கு எதிராக செய்யப்படும் வேலை:','["எதிர்மறை", "நேர்மறை", "பூஜ்யம்", "முடிவில்லாதது"]'::jsonb,'For Q > 0, force is repulsive. Work against repulsion is positive. This positive work is stored as potential energy. | Q > 0 எனில், சோதனை மின்னேற்றத்திற்கு விரட்டும் விசை உண்டு. இந்த விரட்டலுக்கு எதிராக வேலை செய்யப்பட வேண்டும், எனவே வெளிப்புற விசையின் வேலை நேர்மறை.','TAPHY12TA02Q0272','active'),
  ('1e259797-6f94-54dc-b220-ace875c2785c','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு புள்ளி மின்னேற்றத்தின் காரணமாக மின்புலம் E மற்றும் மின்னிலை V தூரம் r உடன் முறையே மாறுவது:','["E ∝ 1/r மற்றும் V ∝ 1/r²", "E ∝ 1/r² மற்றும் V ∝ 1/r", "E ∝ 1/r³ மற்றும் V ∝ 1/r²", "E ∝ 1/r மற்றும் V ∝ 1/r"]'::jsonb,'From Figure 2.4, E ∝ 1/r² (Coulomb''s law) while V ∝ 1/r. Field falls off faster than potential. | படம் 2.4 இன்படி, E ∝ 1/r² மற்றும் V ∝ 1/r. மின்புலம் தூரத்துடன் வேகமாகக் குறைகிறது.','TAPHY12TA02Q0273','active'),
  ('74263b0f-2bc3-589f-978e-dd5971b520c7','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்னிலையின் SI அலகு என்ன?','["Newton/Coulomb", "Joule/Coulomb", "Coulomb/meter", "Volt/meter"]'::jsonb,'Potential is work per unit charge, so SI unit is Joule/Coulomb (J/C) = Volt (V). | மின்னிலை ஒரு அலகு மின்னேற்றத்திற்கான வேலை, எனவே அதன் SI அலகு Joule/Coulomb = Volt.','TAPHY12TA02Q0274','active'),
  ('f104a269-800a-5811-a20f-2963f0eaa4f4','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',0,'A','மின்புலத்தில் R இலிருந்து P க்கு q ஐ நகர்த்தும்போது நிலை ஆற்றல் வேறுபாடு எவ்வாறு கொடுக்கப்படுகிறது?','["ΔU = W_RP", "ΔU = -W_RP", "ΔU = W_RP / q", "ΔU = q × W_RP"]'::jsonb,'ΔU = U_P - U_R = W_RP, where W_RP is work done by external force. This is stated on the page. | நிலை ஆற்றல் வேறுபாடு ΔU = U_P - U_R = W_RP, இங்கு W_RP என்பது R இலிருந்து P க்கு q ஐ நகர்த்துவதற்கான வெளிப்புற விசையின் வேலை.','TAPHY12TA02Q0275','active'),
  ('d0b27c72-6ca5-5834-b109-1df9c8cd1864','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு புள்ளியில் மின்னேற்றத்தின் நிலை ஆற்றல் அதை எங்கிருந்து கொண்டுவருவதற்கான வேலையாக வரையறுக்கப்படுகிறது?','["அப்புள்ளியிலிருந்து முடிவு வரை", "முடிவிலிருந்து அப்புள்ளி வரை", "தரையிலிருந்து அப்புள்ளி வரை", "எந்த குறிப்பு புள்ளியிலிருந்தும் அப்புள்ளி வரை"]'::jsonb,'With potential at infinity as zero, potential energy is work done in bringing charge from infinity to that point. | முடிவில் மின்னிலை பூஜ்யம் எனத் தேர்ந்தெடுக்கும்போது, ஒரு புள்ளியில் q இன் நிலை ஆற்றல் முடிவிலிருந்து அப்புள்ளிக்கு அதைக் கொண்டுவருவதற்கான வேலை.','TAPHY12TA02Q0276','active'),
  ('6306f0f2-d685-5c62-b878-871701a074e6','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','புள்ளி மின்னேற்றத்தின் மின்னிலையைக் கணக்கிட ஒருங்கிணைக்கும் பாதை எது?','["மின்னேற்றத்தைச் சுற்றிய வட்டப் பாதை", "ஆர திசைக்கு செங்குத்தான நேர்க்கோடு", "முடிவிலிருந்து புள்ளிக்கு ஆர வரிசையில்", "எந்த வளைந்த பாதையும்"]'::jsonb,'Path-independent work allows choosing a convenient radial path from infinity to P. This simplifies calculation. | வேலை பாதையைப் பொறுத்தது அல்ல என்பதால், முடிவிலிருந்து P புள்ளிக்கு ஆர வரிசையில் ஒரு வசதியான பாதை தேர்ந்தெடுக்கப்படுகிறது.','TAPHY12TA02Q0277','active'),
  ('7944eed7-23fb-58ba-8ed1-15190c7dd0c9','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஆதிப்புள்ளியில் Q மின்னேற்றத்தின் காரணமாக r நிலை வெக்டரைக் கொண்ட P புள்ளியில் மின்னிலை எதிர்விகிதமாக உள்ளது?','["r²", "r", "r³", "√r"]'::jsonb,'V(r) = Q/(4πε₀r) shows potential is inversely proportional to distance r. | V(r) = Q/(4πε₀r) என்பதால், மின்னிலை தூரம் r உடன் எதிர்விகிதத்தில் உள்ளது.','TAPHY12TA02Q0278','active'),
  ('b1dc94d1-cce0-51d6-9db1-4269825b2362','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','புள்ளி மின்னேற்றத்திலிருந்து தூரம் இரட்டிப்பாகும்போது மின்னிலை என்னவாகிறது?','["நான்கு மடங்கு", "இரட்டிப்பு", "பாதி", "ஒரு கால்"]'::jsonb,'Since V ∝ 1/r, if r doubles, V becomes half. If r → 2r, then V → V/2. | V ∝ 1/r என்பதால், r இரட்டிப்பாகும்போது V பாதியாகிறது.','TAPHY12TA02Q0279','active'),
  ('c8eb3a27-79cf-54af-9d3a-cc84cb9475c6','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','V = Q/(4πε₀r) என்ற வெளிப்பாடு எந்த எல்லை நிபந்தனையுடன் ஒத்துப்போகிறது?','["r = 0 இல் V = 0", "r = ∞ இல் V = 0", "r = ∞ இல் V = ∞", "r = 0 இல் V = Q"]'::jsonb,'As r → ∞, V → 0, consistent with choosing potential at infinity as zero. | r → ∞ எனில் V → 0, இது முடிவில் மின்னிலை பூஜ்யம் என்ற தேர்வுடன் ஒத்துப்போகிறது.','TAPHY12TA02Q0280','active'),
  ('0d9a7043-c4de-50e7-8303-08af6b9c9e64','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','நேர்மறை மின்னேற்றம் Q இன் புலத்தில் P புள்ளியில் ஓய்வில் விடப்பட்ட மின்னேற்றத்தின் நிலை ஆற்றல் என்னவாகிறது?','["தொடர்ந்து அதிகரிக்கிறது", "குறைந்து இயக்க ஆற்றலாக மாறுகிறது", "மாறாதது", "உடனடியாக பூஜ்யமாகிறது"]'::jsonb,'When external force is removed, stored potential energy provides kinetic energy. Total energy is conserved. | வெளிப்புற விசை நீக்கப்படும்போது, சேமிக்கப்பட்ட நிலை ஆற்றல் இயக்க ஆற்றலாக மாறுகிறது, மொத்த ஆற்றல் பாதுகாக்கப்படுகிறது.','TAPHY12TA02Q0281','active'),
  ('5d4c138c-c69e-5410-a394-68a998998350','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','உதாரணம் 2.1 இல் Q = 8 × 10⁻⁷ C ஆக மாற்றப்பட்டால் (தூரம் ஒன்றே), P இல் புதிய மின்னிலை என்ன?','["2 × 10⁴ V", "4 × 10⁴ V", "8 × 10⁴ V", "16 × 10⁴ V"]'::jsonb,'Since V ∝ Q, doubling Q doubles potential. Original V = 4×10⁴ V, new V = 8×10⁴ V. | V ∝ Q என்பதால், Q இரட்டிப்பாகும்போது V இரட்டிப்பாகிறது.','TAPHY12TA02Q0282','active'),
  ('6523b864-c20e-5144-b7e6-207e3cb206bc','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',0,'A','மின்னிலையின் பரிமாண வாய்பாடு என்ன?','["[ML²T⁻³A⁻¹]", "[MLT⁻²A⁻¹]", "[M²L²T⁻³A⁻¹]", "[ML²T⁻²A⁻¹]"]'::jsonb,'Potential = Work/Charge = [ML²T⁻²]/[AT] = [ML²T⁻³A⁻¹]. Matches dimensional table. | மின்னிலை = வேலை/மின்னேற்றம் = [ML²T⁻²]/[AT] = [ML²T⁻³A⁻¹].','TAPHY12TA02Q0283','active'),
  ('e2c6366c-c444-5f16-8e62-6b8786777358','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','நேர்மறை மின்னேற்றம் Q இன் புலத்தில் எதிர்மறை மின்னேற்றம் விடப்பட்டால் அது:','["Q இலிருந்து விலகிச் செல்லும்", "Q நோக்கி நகரும்", "ஓய்வில் இருக்கும்", "வட்டப் பாதையில் நகரும்"]'::jsonb,'Negative charge is attracted toward positive charge. Force is attractive. | எதிர்மறை மின்னேற்றம் நேர்மறை மின்னேற்றத்தை நோக்கி ஈர்க்கப்படும். இந்த ஈர்ப்பு விசையால் அது Q நோக்கி முடுக்கம் பெறும்.','TAPHY12TA02Q0284','active'),
  ('13198a82-e2b1-5fee-a550-d8c23b81409c','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்புலத்தில் ஒரு மின்னேற்றத்தை ஒரு புள்ளியிலிருந்து மற்றொரு புள்ளிக்கு நகர்த்துவதற்கான வேலை எதைப் பொறுத்தது?','["எடுக்கப்பட்ட பாதை", "தொடக்க மற்றும் இறுதி நிலைகள் மட்டுமே", "மின்னேற்றத்தின் வேகம்", "மின்னேற்றத்தின் நிறை"]'::jsonb,'For conservative electrostatic force, work depends only on initial and final positions, not path. | பாதுகாப்பு விசைக்கு, செய்யப்பட்ட வேலை தொடக்க மற்றும் இறுதி நிலைகளை மட்டுமே பொறுத்தது, பாதையை அல்ல.','TAPHY12TA02Q0285','active'),
  ('28fae473-824a-56bb-bb8c-66cf33a3a910','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','ΔW = -(Q/4πε₀r''²)Δr'' வெளிப்பாட்டில் எதிர்மறைக் குறி குறிக்குவது என்ன?','["புலத்தால் வேலை செய்யப்படுகிறது", "புலத்திற்கு எதிராக வேலை செய்யப்படுகிறது", "உள்ளே நகரும்போது வெளிப்புற விசையின் வேலை நேர்மறை", "வெளியே நகரும்போது வேலை நேர்மறை"]'::jsonb,'Negative sign ensures ΔW is positive when Δr'' < 0 (moving inward against repulsion). | எதிர்மறைக் குறி Δr'' < 0 (உள்ளே நகரும்போது) எனில் ΔW நேர்மறை என்பதை உறுதி செய்கிறது.','TAPHY12TA02Q0286','active'),
  ('0f1125f7-4591-5210-af7c-58c4bd33027a','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','புள்ளி மின்னேற்றத்தின் காரணமாக ஒரு புள்ளியில் மின்னிலை ஒரு அடிமான அளவு, ஏனெனில்:','["அதற்கு அளவும் திசையும் உள்ளன", "அதற்கு அளவு மட்டுமே உள்ளது, திசை இல்லை", "அது வெக்டர் மின்புலத்திலிருந்து பெறப்படுகிறது", "பயன்படுத்தப்படும் சோதனை மின்னேற்றத்தைப் பொறுத்தது"]'::jsonb,'Potential is scalar as it represents work per unit charge. It has magnitude but no direction. | மின்னிலை ஒரு அடிமான அளவு, ஏனெனில் இது வேலை/மின்னேற்றம் என்பது அடிமான. திசை இல்லாமல் அளவு மட்டுமே உள்ளது.','TAPHY12TA02Q0287','active'),
  ('1563ac5b-de0c-5aee-a09e-144597ff58e5','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','இரண்டு எதிர் மின்னேற்றங்களை இணைக்கும் கோட்டின் செங்குத்துப் பக்கப்படுத்தியில் உள்ள எந்தவொரு புள்ளியிலும் மின்னிலை:','["எப்போதும் நேர்மறை", "எப்போதும் எதிர்மறை", "பூஜ்யம்", "தூரத்தைப் பொறுத்தது"]'::jsonb,'On the equatorial plane, potentials due to +q and -q cancel out, giving V = 0. This is a dipole property. | இரண்டு எதிர் மின்னேற்றங்களின் சமபக்கப்படுத்தியில், +q மற்றும் -q இன் மின்னிலைகள் நீக்கப்பட்டு V = 0 ஆகிறது.','TAPHY12TA02Q0288','active'),
  ('c9021488-137f-5d1d-be1f-d490e816af32','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு புள்ளி மின்னேற்றத்திற்கு r தூரத்தில் மின்புலம் E மற்றும் மின்னிலை V இன் விகிதம் எதிர்விகிதமாக உள்ளது?','["r", "1/r", "1/r²", "r²"]'::jsonb,'E = Q/(4πε₀r²) and V = Q/(4πε₀r), so E/V = 1/r. Thus E/V ∝ 1/r. | E = Q/(4πε₀r²) மற்றும் V = Q/(4πε₀r), எனவே E/V = 1/r.','TAPHY12TA02Q0289','active'),
  ('018cd337-c954-556b-9aad-f2658c42f9fb','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','இரண்டு சம நேர்மறை மின்னேற்றங்கள் ஒரு தூரத்தில் வைக்கப்பட்டால், அவற்றின் இடையே உள்ள நடுப்புள்ளியில் மின்னிலை:','["பூஜ்யம்", "ஒரு மின்னேற்றத்தின் மின்னிலையை விட இரட்டிப்பு", "ஒரு மின்னேற்றத்தின் மின்னிலையின் பாதி", "ஒரு மின்னேற்றத்தின் மின்னிலைக்கு சமம்"]'::jsonb,'By superposition, potentials add algebraically. At midpoint, each contributes equally, so total is twice one charge''s potential. | மேலடுக்கு கொள்கையால், மின்னிலைகள் கூட்டப்படுகின்றன. நடுப்புள்ளியில் ஒவ்வொரு மின்னேற்றமும் சமமாக பங்களிக்கிறது.','TAPHY12TA02Q0290','active'),
  ('edb53599-e6bf-5c30-8c8d-8d6f97705002','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','இரண்டு புள்ளிகளுக்கு இடையே நிலை ஆற்றல் வேறுபாடு மட்டுமே முக்கியமானது, ஏனெனில்:','["அது எடுக்கப்பட்ட பாதையைப் பொறுத்தது", "அது மின்னிலையில் உள்ள கூட்டல் மாறிலியைப் பொறுத்தது அல்ல", "பூஜ்ய மின்னிலை தேர்வுடன் அது மாறுகிறது", "அது எப்போதும் எதிர்மறை"]'::jsonb,'Actual potential energy is undetermined to within an additive constant. Only difference is significant as constant cancels: (U_P + α) - (U_R + α) = U_P - U_R. | நிலை ஆற்றலின் உண்மை மதிப்பு ஒரு கூட்டல் மாறிலிக்குள் உறுதியற்றது. வேறுபாடு மட்டுமே முக்கியமானது, ஏனெனில் மாறிலி நீக்கப்படுகிறது.','TAPHY12TA02Q0291','active'),
  ('2cc2cd6e-866c-57d9-bace-ef2270cf48c6','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மீத்தொகைக் கொள்கையின்படி, மின்சுமைகளின் தொகுப்பால் ஒரு புள்ளி P இல் உண்டாகும் மின்னழுத்தம் எவ்வாறு கணக்கிடப்படுகிறது?','["தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களின் பெருக்கல்", "தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களின் இயற்கணிதக் கூட்டுத்தொகை", "தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களின் வெக்டர் கூட்டுத்தொகை", "மிகப்பெரிய மற்றும் மிகச்சிறிய மின்னழுத்தங்களுக்கு இடையேயான வித்தியாசம்"]'::jsonb,'The superposition principle states that the total potential V at point P is the algebraic sum V = V1 + V2 + ... + Vn of potentials due to each individual charge. Since potential is a scalar quantity, we add them algebraically, not vectorially. | மின்னழுத்தம் ஒரு அளவுரு (scalar) என்பதால், மீத்தொகைக் கொள்கையின்படி புள்ளி P இல் மொத்த மின்னழுத்தம் V = V1 + V2 + ... + Vn என்று தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களின் இயற்கணிதக் கூட்டுத்தொகையாகும்.','TAPHY12TA02Q0292','active'),
  ('952de215-13be-5d6f-9ad3-8de0c67e0ba5','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',0,'A','சீராக மின்சுமையேற்றப்பட்ட கோளப்பட்டைக்கு வெளிப்புறத்தில் (r ≥ R) மின்னழுத்தம் எதற்கு சமமாக இருக்கும்?','["கோளப்பட்டையின் மையத்தில் Q மின்சுமை குவித்திருப்பது போன்ற புள்ளி மின்சுமையின் மின்னழுத்தம்", "R ஆரமுள்ள சீராக மின்சுமையேற்றப்பட்ட திண்மக் கோளத்தின் மின்னழுத்தம்", "எங்கும் சுழிய மின்னழுத்தம்", "1/r² வகையில் மாறும் மின்னழுத்தம்"]'::jsonb,'For a uniformly charged spherical shell, the electric field outside is the same as if all charge Q were concentrated at the center. Therefore, the potential outside is V = (1/4πε₀)(q/r), identical to a point charge at the center. | சீராக மின்சுமையேற்றப்பட்ட கோளப்பட்டைக்கு, வெளிப்புறம் மின்விசை மையத்தில் Q மின்சுமை குவித்தது போலவே உள்ளது. எனவே வெளிப்புற மின்னழுத்தம் V = (1/4πε₀)(q/r), மையத்தில் ஒரு புள்ளி மின்சுமையைப் போன்றது.','TAPHY12TA02Q0293','active'),
  ('40796b2c-3a70-5913-83d2-934b81385a5a','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்சுமைகளின் தொகுப்பு q1, q2, ..., qn கொண்ட புள்ளி P இல் மின்னழுத்தம் எந்தச் சூத்திரத்தால் தரப்படுகிறது?','["V = (1/4πε₀) × (q₁/r₁ₚ² + q₂/r₂ₚ² + ... + qₙ/rₙₚ²)", "V = (1/4πε₀) × (q₁/r₁ₚ + q₂/r₂ₚ + ... + qₙ/rₙₚ)", "V = 4πε₀ × (q₁/r₁ₚ + q₂/r₂ₚ + ... + qₙ/rₙₚ)", "V = (1/4πε₀) × (q₁×r₁ₚ + q₂×r₂ₚ + ... + qₙ×rₙₚ)"]'::jsonb,'The potential due to a point charge is V = (1/4πε₀)(q/r). For a system of charges, by superposition, the total potential is the sum of individual potentials: V = (1/4πε₀)Σ(qᵢ/rᵢₚ). Note that potential depends on 1/r, not 1/r² (which is for electric field). | புள்ளி மின்சுமையின் மின்னழுத்தம் V = (1/4πε₀)(q/r). மின்சுமைகளின் தொகுப்புக்கு, மீத்தொகைக் கொள்கையால் V = (1/4πε₀)Σ(qᵢ/rᵢₚ). மின்னழுத்தம் 1/r இல் சாரும், 1/r² இல் அல்ல (அது மின்விசைக்கு).','TAPHY12TA02Q0294','active'),
  ('56b9497e-2142-56c8-bdec-1f41bdb4030b','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','கோளப்பட்டைக்குள் உள்ள மின்னழுத்தத்தின் தன்மை என்ன?','["உள்ளே எங்கும் சுழியம்", "மாறிலி, மேற்பரப்பு மின்னழுத்தத்திற்கு சமம்", "மையத்திலிருந்து தூரத்துடன் நேர்கோட்டில் மாறும்", "மையத்திலிருந்து 1/r வகையில் மாறும்"]'::jsonb,'Since the electric field inside a charged spherical shell is zero (E=0), no work is done in moving a charge inside. Therefore, the potential is constant throughout the interior and equals the potential at the surface: V = (1/4πε₀)(q/R). | கோளப்பட்டைக்குள் மின்விசை சுழியம் (E=0), எனவே உள்ளே மின்சுமையை நகர்த்த எந்த வேலையும் செய்ய வேண்டியதில்லை. எனவே உள்ளக மின்னழுத்தம் மாறிலியாகவும், மேற்பரப்பு மின்னழுத்தத்திற்கு சமமாகவும் உள்ளது: V = (1/4πε₀)(q/R).','TAPHY12TA02Q0295','active'),
  ('17a4afde-6ef4-5793-9491-b24f4fcc82b3','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',0,'A','மின்சுமை அடர்த்தி ρ(r) கொண்ட தொடர்ச்சியான மின்சுமைப் பரவலுக்கு மின்னழுத்தம் எவ்வாறு கணக்கிடப்படுகிறது?','["சிறிய கனவளவு கூறுகளின் மின்னழுத்தங்களைக் கூட்டுவதால், ஒவ்வொன்றும் ρΔv மின்சுமையைக் கொண்டிருக்கும்", "மின்விசைகளின் வெக்டர் கூட்டுத்தொகையை எடுத்து பின்னர் ஒருங்கிணைப்பது", "மொத்த மின்சுமையை புள்ளிக்கான தூரத்தால் பெருக்குவது", "மேற்பரப்பு மின்சுமை அடர்த்தியை மட்டும் பயன்படுத்தி கனவளவு கூறுகளை புறக்கணிப்பது"]'::jsonb,'For continuous charge distributions, we divide the distribution into small volume elements of size Δv, each carrying charge ρΔv. We calculate the potential due to each element and integrate (sum) over all contributions to get the total potential. | தொடர்ச்சியான மின்சுமைப் பரவலுக்கு, அதை Δv அளவுள்ள சிறிய கனவளவு கூறுகளாகப் பிரிக்கிறோம், ஒவ்வொன்றும் ρΔv மின்சுமையைக் கொண்டிருக்கும். ஒவ்வொரு கூறின் மின்னழுத்தத்தைக் கணக்கிட்டு, அனைத்தையும் தொகுத்து (ஒருங்கிணைத்து) மொத்த மின்னழுத்தத்தைப் பெறுகிறோம்.','TAPHY12TA02Q0296','active'),
  ('589492e2-2ec0-5dff-b0a5-bd81c4549a1a','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','V = (1/4πε₀)(q₁/r₁ₚ + q₂/r₂ₚ + ...) சூத்திரத்தில் r₁ₚ என்றால் என்ன?','["மையத்தைச் சார்ந்த q₁ இன் இடவெக்டர்", "மின்சுமை q₁க்கும் புள்ளி Pக்கும் இடையேயான தூரம்", "P இலிருந்து q₁ இல் உள்ள மின்விசையின் வலிமை", "புள்ளி P இல் q₁ இன் நிலை ஆற்றல்"]'::jsonb,'r₁ₚ represents the distance between charge q₁ and the point P where potential is being calculated. Similarly, r₂ₚ is the distance between q₂ and P, and so on for all charges in the system. | r₁ₚ என்பது மின்சுமை q₁க்கும் மின்னழுத்தம் கணக்கிடப்படும் புள்ளி Pக்கும் இடையேயான தூரத்தைக் குறிக்கிறது. அதுபோல r₂ₚ என்பது q₂க்கும் Pக்கும் இடையேயான தூரம்.','TAPHY12TA02Q0297','active'),
  ('e072ce03-8f15-5109-ab17-1bcb1c6d4150','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்நிலையியல் மின்னழுத்தத்திற்கு மீத்தொகைக் கொள்கை செல்லுபடியாவதற்கான காரணம் என்ன?','["கூலம்பின் விசை ஒரு காப்பில்லா விசை (non-conservative force)", "கூலம்பின் விசை தலைகீழ் வர்க்க விதியைப் பின்பற்றுகிறது", "மின்நிலையியல் விசை காப்பு விசையாகவும், செய்யப்படும் வேலை பாதையற்றது", "மின்னழுத்தம் ஒரு வெக்டர் அளவுரு, அதைப் பிரிக்கலாம்"]'::jsonb,'The superposition principle holds because electrostatic force is conservative. The work done (and hence potential) depends only on initial and final positions, not on the path. This allows us to add potentials from individual charges algebraically. | மின்நிலையியல் விசை ஒரு காப்பு விசை (conservative force) என்பதால் மீத்தொகைக் கொள்கை செல்லுபடியாகிறது. செய்யப்படும் வேலை (எனவே மின்னழுத்தம்) தொடக்க மற்றும் இறுதி நிலைகளை மட்டுமே சார்ந்தது, பாதையை அல்ல. இது தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களை இயற்கணிதமாகக் கூட்ட அனுமதிக்கிறது.','TAPHY12TA02Q0298','active'),
  ('86a01b0d-3d09-52fa-9d51-553ebca9d854','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு கோளப்பட்டையின் மேற்பரப்பில் மின்னழுத்தம் எவ்வாறு கணக்கிடப்படுகிறது?','["V = (1/4πε₀)(q/R²)", "V = (1/4πε₀)(q/R)", "V = 4πε₀(q/R)", "V = (1/4πε₀)(q×R)"]'::jsonb,'At the surface of a uniformly charged spherical shell (r = R), the potential is V = (1/4πε₀)(q/R). This is the same as the potential just outside, and since potential is constant inside, it is also the potential throughout the interior. | சீராக மின்சுமையேற்றப்பட்ட கோளப்பட்டையின் மேற்பரப்பில் (r = R), மின்னழுத்தம் V = (1/4πε₀)(q/R). இது வெளிப்புறத்தில் உள்ள மின்னழுத்தத்திற்கு சமம், மேலும் உள்ளக மின்னழுத்தம் மாறிலியாக இருப்பதால் இது உள்ளேயும் ஒரே மதிப்பாக இருக்கும்.','TAPHY12TA02Q0299','active'),
  ('0669f9e8-2d99-53c4-b79e-118d8490abe2','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',3,'D','சமநிலை மின்னழுத்த மேற்பரப்பு B இலிருந்து A க்கு ஒரு அலகு நேர்மின் மின்னேற்றத்தை நகர்த்துவதற்கான வேலை என்ன?','["|E| × dl", "V - (V + dV)", "-dV", "மேற்கண்ட அனைத்தும்"]'::jsonb,'The work done equals |E|dl, which also equals V - (V+dV) = -dV. All three expressions are equivalent. | | செய்யப்பட்ட வேலை |E|dl க்கு சமம், இது V - (V+dV) = -dV க்கும் சமம். மூன்று வெளிப்பாடுகளும் சமமானவை.','TAPHY12TA02Q0300','active'),
  ('69197fc5-d54c-59d2-8b11-37d4afa798ad','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்புலம் E இன் அளவு மற்றும் செங்குத்து தூர l உடன் மின்னழுத்த V இன் மாற்ற வீதம் இடையேயான உறவு என்ன?','["|E| = dV/dl", "|E| = -dV/dl", "|E| = V × l", "|E| = V/l"]'::jsonb,'From the derivation, |E| = -dV/dl = +|dV|/dl. The negative sign indicates E points in direction of decreasing potential. | | வழிநடத்தலிலிருந்து, |E| = -dV/dl = +|dV|/dl. எதிர்குறி E குறைந்து வரும் மின்னழுத்தத்தின் திசையைக் குறிக்கிறது.','TAPHY12TA02Q0301','active'),
  ('9e063770-bedb-5b43-8284-93ffbceab051','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்புலம் எந்த திசையில் சுட்டிக்காட்டுகிறது?','["கடுமையான மின்னழுத்த அதிகரிப்பின் திசை", "கடுமையான மின்னழுத்த குறைவின் திசை", "மின்னழுத்த சாய்வுக்கு செங்குத்தான திசை", "சமநிலை மின்னழுத்த மேற்பரப்புகளுக்கு இணையான திசை"]'::jsonb,'Electric field is in the direction in which the potential decreases steepest. This is a key conclusion from the field-potential relation. | | மின்புலம் மின்னழுத்தம் கடுமையாகக் குறையும் திசையில் இருக்கும். இது மின்புலம்-மின்னழுத்த உறவிலிருந்து வரும் முக்கிய முடிவு.','TAPHY12TA02Q0302','active'),
  ('5d28b6e6-a468-5ccd-97a6-b4a7a0418e50','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்புலத்தின் அளவு எதனால் கொடுக்கப்படுகிறது?','["சமநிலை மேற்பரப்பிற்கு இணையான அலகு இடப்பெயர்வுக்கு மின்னழுத்த மாற்றம்", "சமநிலை மேற்பரப்பிற்கு செங்குத்தான அலகு இடப்பெயர்வுக்கு மின்னழுத்த மாற்றம்", "மொத்த மின்னழுத்தம் பகுதிக்கு மொத்த தூரம்", "மின்னழுத்த வேறுபாடு தூரத்தால் பெருக்கப்பட்டது"]'::jsonb,'The magnitude of E is given by the change in potential per unit displacement normal to the equipotential surface. | | E இன் அளவு சமநிலை மின்னழுத்த மேற்பரப்பிற்கு செங்குத்தான அலகு இடப்பெயர்வுக்கு மின்னழுத்தத்தின் மாற்றத்தால் கொடுக்கப்படுகிறது.','TAPHY12TA02Q0303','active'),
  ('44132b9d-7cbc-5c0d-8869-fac5ef6e82bb','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','இரண்டு மின்னேற்றங்கள் q1 மற்றும் q2 இன் அமைப்பை உருவாக்கும்போது, முதல் மின்னேற்றம் q1 ஐ முடிவிலிருந்து r1 க்கு கொண்டு வருவதற்கான வேலை என்ன?','["q1 × V2", "(1/4πε0)(q1q2/r12)", "பூஜ்யம்", "முடிவில்லாதது"]'::jsonb,'When bringing q1 first, there is no external field against which work needs to be done, so work done is zero. | | q1 ஐ முதலில் கொண்டு வரும்போது, வேலை செய்ய வேண்டிய வெளிப்புற புலம் இல்லை, எனவே செய்யப்பட்ட வேலை பூஜ்யம்.','TAPHY12TA02Q0304','active'),
  ('18aadd8e-0c44-5ecd-97fd-5cf2a7d82346','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','r12 தூரத்தில் பிரிக்கப்பட்ட இரண்டு மின்னேற்றங்கள் q1 மற்றும் q2 இன் அமைப்பின் நிலையாற்றல் என்ன?','["(1/4πε0)(q1 + q2)/r12", "(1/4πε0)(q1q2/r12)", "(1/4πε0)(q1 - q2)/r12", "(1/4πε0)(q1q2/r12²)"]'::jsonb,'The potential energy U = (1/4πε0)(q1q2/r12). This represents work done in assembling the configuration. | | நிலையாற்றல் U = (1/4πε0)(q1q2/r12). இது அமைப்பை உருவாக்குவதற்கான வேலையைக் குறிக்கிறது.','TAPHY12TA02Q0305','active'),
  ('f74fd422-2ada-53e2-8496-23075e5d9d3d','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','இரண்டு ஒத்த மின்னேற்றங்களுக்கு (இரண்டும் நேர்மறை அல்லது இரண்டும் எதிர்மறை) நிலையாற்றலின் குறி என்ன?','["எதிர்மறை", "நேர்மறை", "பூஜ்யம்", "தூரத்தை மட்டுமே சார்ந்தது"]'::jsonb,'For like charges (q1q2 > 0), electrostatic force is repulsive and positive work is needed, so potential energy is positive. | | ஒத்த மின்னேற்றங்களுக்கு (q1q2 > 0), மின்நிலை விசை விரிவாக்கும் விசையாகும் மற்றும் நேர்மறை வேலை தேவைப்படுகிறது, எனவே நிலையாற்றல் நேர்மறை.','TAPHY12TA02Q0306','active'),
  ('74b2b2a3-f8d7-5fa0-b70f-a5d8bbaa7174','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','இரண்டு வேறுபட்ட மின்னேற்றங்களுக்கு (ஒன்று நேர்மறை மற்றொன்று எதிர்மறை) நிலையாற்றலின் குறி என்ன?','["நேர்மறை", "எதிர்மறை", "பூஜ்யம்", "எப்போதும் முடிவில்லாதது"]'::jsonb,'For unlike charges (q1q2 < 0), electrostatic force is attractive and negative work is needed for reverse path, so potential energy is negative. | | வேறுபட்ட மின்னேற்றங்களுக்கு (q1q2 < 0), மின்நிலை விசை ஈர்க்கும் விசையாகும் மற்றும் தலைகீழ் பாதைக்கு எதிர்மறை வேலை தேவைப்படுகிறது, எனவே நிலையாற்றல் எதிர்மறை.','TAPHY12TA02Q0307','active'),
  ('647d2495-00d0-537b-8544-7d32d3da15e5','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மூன்று மின்னேற்றங்கள் q1, q2, மற்றும் q3 இன் அமைப்பின் நிலையாற்றல் என்ன?','["தனித்தனி நிலையாற்றல்களின் கூடுதல் மட்டுமே", "(1/4πε0)[(q1q2/r12) + (q1q3/r13) + (q2q3/r23)]", "(1/4πε0)[(q1q2q3)/(r12r13r23)]", "அனைத்து மின்னேற்றங்களின் பெருக்கல் தூரங்களின் கூடுதலால் பகுக்கப்பட்டது"]'::jsonb,'The total potential energy is the sum of potential energies for each pair of charges. | | மொத்த நிலையாற்றல் ஒவ்வொரு மின்னேற்ற ஜோடிக்கான நிலையாற்றல்களின் கூடுதல்.','TAPHY12TA02Q0308','active'),
  ('d28356d0-64a5-5588-bde8-ab9f42efc4d2','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்னேற்ற அமைப்பின் நிலையாற்றல் அமைப்பை உருவாக்க பயன்படுத்தப்பட்ட பாதையைச் சார்ந்ததா?','["ஆம், குறிப்பிட்ட பாதையைச் சார்ந்தது", "இல்லை, மின்நிலை விசையின் பாதுகாப்பு தன்மையால் பாதை சாராதது", "இரண்டு மின்னேற்றங்களுக்கு மட்டுமே, அதற்கு மேல் அல்ல", "மின்னேற்றங்களைக் கொண்டு வரும் வரிசையைச் சார்ந்தது"]'::jsonb,'Because of conservative nature of electrostatic force, potential energy is independent of the path or manner of assembly. | | மின்நிலை விசையின் பாதுகாப்பு தன்மையால், நிலையாற்றல் பாதை அல்லது உருவாக்க முறை சார்ந்ததல்ல.','TAPHY12TA02Q0309','active'),
  ('9a04ef28-32d2-5bf0-94df-65d24ef26323','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்னேற்ற அமைப்பின் நிலையாற்றல் எதைச் சிறப்பிக்கிறது?','["மின்னேற்றங்களை உருவாக்க பயன்படுத்தப்பட்ட பாதை", "தற்போதைய அமைப்பின் நிலை மட்டுமே", "மின்னேற்றங்கள் கொண்டு வரப்பட்ட வரிசை", "உருவாக்கத்தின் போது பயன்படுத்தப்பட்ட வெளிப்புற விசைகள்"]'::jsonb,'The potential energy is characteristic of the present state of configuration, not the way the state is achieved. | | நிலையாற்றல் தற்போதைய அமைப்பின் நிலையைச் சார்ந்தது, அந்த நிலை எவ்வாறு அடையப்பட்டது என்பதை அல்ல.','TAPHY12TA02Q0310','active'),
  ('4ba56122-9a6a-548e-95d8-4e5517a9fe95','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','மின்னேற்றம் q2 முதலில் கொண்டு வரப்பட்டு பின்னர் q1 கொண்டு வரப்பட்டால், நிலையாற்றல் எவ்வாறு மாறும்?','["வேறுபடும்", "ஒரே மாதிரியாக இருக்கும்", "இரட்டிப்பாகும்", "பாதியாகும்"]'::jsonb,'The potential energy would be the same regardless of order due to conservative nature of electrostatic force. | | மின்னேற்றங்கள் கொண்டு வரப்பட்ட வரிசையைப் பொருட்படுத்தாமல் நிலையாற்றல் ஒரே மாதிரியாக இருக்கும், மின்நிலை விசையின் பாதுகாப்பு தன்மையால்.','TAPHY12TA02Q0311','active'),
  ('4ee6d5fe-bfa2-58c7-b3d8-a4a8a1abe478','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','q2 ஐ முடிவிலிருந்து r2 இடத்திற்கு கொண்டு வரும்போது q1 க்குரிய மின்னழுத்தத்தின் அடிப்படையில் q2 மீது செய்யப்பட்ட வேலை என்ன?','["q2 வகுத்தல் V1", "q2 பெருக்கப்பட்டது V1 at r2", "V1 வகுத்தல் q2", "q2 கூட்டல் V1 at r2"]'::jsonb,'Work done on q2 = q2 × V1(r2), where V1 is potential due to q1 at position r2. | | q2 மீது செய்யப்பட்ட வேலை = q2 × V1(r2), இங்கு V1 என்பது q1 ஆல் r2 இடத்தில் உருவாக்கப்படும் மின்னழுத்தம்.','TAPHY12TA02Q0312','active'),
  ('366839b4-2866-50a8-9730-de575c76d32d','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','U = (1/4πε0)(q1q2/r12) வெளிப்பாட்டில் U எதிர்மறையாக இருக்க என்ன நிபந்தனை?','["இரண்டு மின்னேற்றங்களும் நேர்மறை", "இரண்டு மின்னேற்றங்களும் எதிர்மறை", "ஒரு மின்னேற்றம் நேர்மறை மற்றொன்று எதிர்மறை", "மின்னேற்றங்கள் அளவில் சமம்"]'::jsonb,'U is negative when q1q2 < 0, which occurs when one charge is positive and other is negative. | | U எதிர்மறையாக இருக்கும் போது q1q2 < 0, இது ஒரு மின்னேற்றம் நேர்மறை மற்றொன்று எதிர்மறையாக இருக்கும் போது நிகழ்கிறது.','TAPHY12TA02Q0313','active'),
  ('4badacbe-f369-57d3-874d-50c747f0c351','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','நிலையாற்றல் வாய்ப்பாட்டில் மாறி r12 எதைக் குறிக்கிறது?','["q1 இலிருந்து மையப்புள்ளிக்கான தூரம்", "q2 இலிருந்து மையப்புள்ளிக்கான தூரம்", "மின்னேற்றங்கள் q1 மற்றும் q2 இடையேயான தூரம்", "q1 மற்றும் q2 இலிருந்து மையப்புள்ளிக்கான தூரங்களின் கூடுதல்"]'::jsonb,'r12 represents the distance between the two points where charges q1 and q2 are located. | | r12 என்பது மின்னேற்றங்கள் q1 மற்றும் q2 உள்ள இரண்டு புள்ளிகளுக்கு இடையேயான தூரத்தைக் குறிக்கிறது.','TAPHY12TA02Q0314','active'),
  ('09ea4b58-2ecf-5b83-88dd-a814a80fe022','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',0,'A','எடுத்துக்காட்டு 2.4 இல், நான்கு மின்னூட்டங்கள் (+q, -q, +q, -q) d பக்கம் கொண்ட சதுரத்தின் மூலைகளில் வைக்கப்பட்டுள்ளன. இந்த அமைப்பை உருவாக்க தேவையான மொத்த வேலை என்ன?','["-q²/(4πε₀d) × (4 - √2)", "-q²/(4πε₀d) × (4 + √2)", "+q²/(4πε₀d) × (4 - √2)", "-q²/(4πε₀d) × (2 - √2)"]'::jsonb,'The total work is calculated by bringing each charge one by one from infinity. All pair contributions are summed: adjacent pairs give -q²/(4πε₀d) and diagonal pairs give +q²/(4πε₀d√2). The final result is -q²/(4πε₀d) × (4 - √2). | மொத்த வேலை ஒவ்வொரு மின்னூட்டத்தையும் முடிவிலியிலிருந்து ஒவ்வொன்றாகக் கொண்டுவருவதன் மூலம் கணக்கிடப்படுகிறது. அருகிலுள்ள ஜோடிகள் -q²/(4πε₀d) மற்றும் மூலைவிட்ட ஜோடிகள் +q²/(4πε₀d√2) தருகின்றன. இறுதி முடிவு -q²/(4πε₀d) × (4 - √2).','TAPHY12TA02Q0315','active'),
  ('5938994e-628c-5639-8eb9-87c30727208b','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','எடுத்துக்காட்டு 2.4 இல், நான்கு மூலை மின்னூட்டங்கள் நிலையாக வைக்கப்பட்டிருக்கும்போது, q₀ என்ற மின்னூட்டத்தை சதுரத்தின் மையம் E க்கு கொண்டுவர கூடுதல் வேலை என்ன?','["q₀²/(4πε₀d)", "q₀ × q/(4πε₀d)", "பூஜ்ஜியம்", "q₀²/(4πε₀d√2)"]'::jsonb,'The potential at center E is zero because +q charges at A and C cancel the effect of -q charges at B and D. Work done = q₀ × V = 0. | மையம் E இல் மின்னழுத்தம் பூஜ்ஜியம், ஏனெனில் A மற்றும் C இல் உள்ள +q மின்னூட்டங்கள் B மற்றும் D இல் உள்ள -q மின்னூட்டங்களின் விளைவை ரத்து செய்கின்றன. செய்யப்படும் வேலை = q₀ × V = 0.','TAPHY12TA02Q0316','active'),
  ('404b0e2b-f8e6-59e8-bed4-ebe5e0095615','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','பிரிவு 2.8.1 இன்படி, V(r) மின்னழுத்தம் கொண்ட வெளிப்புற மின்புலத்தில் q மின்னூட்டத்தின் நிலை ஆற்றல் என்ன?','["q²V(r)", "qV(r)", "V(r)/q", "q²/V(r)"]'::jsonb,'The potential energy of charge q in external field is U = qV(r). Potential is work per unit charge, so for charge q, energy is q times potential. | வெளிப்புற புலத்தில் q மின்னூட்டத்தின் நிலை ஆற்றல் U = qV(r). மின்னழுத்தம் ஒரு அலகு மின்னூட்டத்திற்கு செய்யப்படும் வேலை, எனவே q மின்னூட்டத்திற்கு ஆற்றல் q மடங்கு மின்னழுத்தம்.','TAPHY12TA02Q0317','active'),
  ('3f153282-a5a7-5d69-9a27-37d889372686','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','வெளிப்புற புலத்தில் q₁ மற்றும் q₂ என்ற இரண்டு மின்னூட்டங்கள் கொண்ட அமைப்பின் மொத்த நிலை ஆற்றல் என்ன?','["q₁V(r₁) + q₂V(r₂)", "q₁V(r₁) + q₂V(r₂) + q₁q₂/(4πε₀r₁₂)", "q₁q₂/(4πε₀r₁₂) மட்டுமே", "q₁V(r₁) - q₂V(r₂)"]'::jsonb,'Total energy has three components: energy of q₁ in external field, energy of q₂ in external field, and mutual interaction energy between the two charges. | மொத்த ஆற்றல் மூன்று கூறுகளைக் கொண்டுள்ளது: வெளிப்புற புலத்தில் q₁ இன் ஆற்றல், q₂ இன் ஆற்றல், மற்றும் இரண்டு மின்னூட்டங்களுக்கிடையேயான相互 செயல்பாட்டு ஆற்றல்.','TAPHY12TA02Q0318','active'),
  ('eb0caf7f-4031-51ff-8be6-5df051b62791','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','எடுத்துக்காட்டு 2.5 இல், 7μC மற்றும் -2μC மின்னூட்டங்கள் முறையே (-9cm, 0, 0) மற்றும் (9cm, 0, 0) இல் வைக்கப்பட்டுள்ளன. இந்த அமைப்பின் மின்னியக்கவியல் நிலை ஆற்றல் என்ன?','["+0.7 J", "-0.7 J", "+0.07 J", "-0.07 J"]'::jsonb,'Using U = (1/4πε₀) × q₁q₂/r with the given values: U = 9×10⁹ × (7×(-2)×10⁻¹²)/0.18 = -0.7 J. The negative sign indicates attractive force. | கொடுக்கப்பட்ட மதிப்புகளுடன் U = (1/4πε₀) × q₁q₂/r சூத்திரத்தைப் பயன்படுத்தி: U = 9×10⁹ × (7×(-2)×10⁻¹²)/0.18 = -0.7 J. எதிர்குறி ஈர்ப்பு விசையைக் குறிக்கிறது.','TAPHY12TA02Q0319','active'),
  ('3efe481b-acf9-592e-ac81-20a944ab7bfe','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','எடுத்துக்காட்டு 2.5 இல் உள்ள இரண்டு மின்னூட்டங்களையும் ஒன்றிலிருந்து மற்றொன்று முடிவிலியளவு தூரத்திற்கு பிரிக்க எவ்வளவு வேலை தேவை?','["0 J", "-0.7 J", "+0.7 J", "1.4 J"]'::jsonb,'Work = U_final - U_initial = 0 - (-0.7) = +0.7 J. Positive work must be done against attractive force to separate the charges to infinity. | வேலை = U_இறுதி - U_ஆரம்பம் = 0 - (-0.7) = +0.7 J. மின்னூட்டங்களை முடிவிலிக்குப் பிரிக்க ஈர்ப்பு விசைக்கு எதிராக நேர்மறை வேலை செய்யப்பட வேண்டும்.','TAPHY12TA02Q0320','active'),
  ('bdce1943-6b53-5c16-acc2-515042e32e90','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','திசையன் p கொண்ட மின் இருமுனை, சீரான மின்புல E இல் θ கோணத்தில் வைக்கப்பட்டுள்ளது. இதன் நிலை ஆற்றல் என்ன?','["pE sin θ", "-pE cos θ", "pE cos θ", "-pE sin θ"]'::jsonb,'The potential energy of a dipole in uniform electric field is U = -p·E = -pE cos θ. The dipole aligns with the field to minimize energy. | சீரான மின்புலத்தில் இருமுனையின் நிலை ஆற்றல் U = -p·E = -pE cos θ. ஆற்றலைக் குறைக்க இருமுனை புலத்திற்கு இணையாக சீரமையும்.','TAPHY12TA02Q0321','active'),
  ('437c2bed-4610-5b26-bbda-e34094d8aee0','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','நிலையான நிலையில் ஒரு கடத்தியின் உள்ளே மின்புலத்தின் மதிப்பு என்ன?','["வெளிப்புற மின்புலத்திற்கு சமம்", "கடத்தி உள்ளே எங்கும் பூஜ்யம்", "மின்னேற்ற அடர்த்திக்கு விகிதாசாரம்", "மையத்தில் அதிகபட்சம்"]'::jsonb,'In a static situation, the electric field is zero everywhere inside a conductor. This is because free electrons redistribute themselves until the internal field cancels any external field. | நிலையான நிலையில், கடத்தி உள்ளே மின்புலம் பூஜ்யமாக இருக்கும். இது ஏனெனில் கட்டுப்படுத்தப்படாத மின்னணுக்கள் மறுபகிர்வு செய்யப்பட்டு, வெளிப்புற மின்புலத்தை நீக்கும் வரை மின்புலம் பூஜ்யமாகிறது.','TAPHY12TA02Q0322','active'),
  ('872d2ede-a329-563f-a553-026bc345e7c5','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்னேற்றம் கொண்ட கடத்தியின் மேற்பரப்பில் மின்புலம் எவ்வாறு இருக்க வேண்டும்?','["மேற்பரப்பிற்கு இணையாக", "மேற்பரப்பிற்கு தொடுவானதாக", "ஒவ்வொரு புள்ளியிலும் மேற்பரப்பிற்கு செங்குத்தாக", "மேற்பரப்பிற்கு 45 பாகை கோணத்தில்"]'::jsonb,'If the field were not normal to the surface, it would have a non-zero component along the surface. Free charges would then experience force and move, violating the static condition. | மின்புலம் மேற்பரப்பிற்கு செங்குத்தாக இல்லையெனில், மேற்பரப்பு வழியாக ஒரு பூஜ்யமற்ற கூறு இருக்கும். அப்போது கட்டுப்படுத்தப்படாத மின்னேற்றங்கள் விசையை அனுபவித்து நகரும், இது நிலையான நிலைமையை மீறுகிறது.','TAPHY12TA02Q0323','active'),
  ('37082d9f-2c6e-5f01-b999-889a0a746967','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','நிலையான நிலையில், மிகை மின்னேற்றம் கடத்தியில் எங்கு அமர்ந்திருக்கும்?','["கன அளவு முழுவதும் சீராக பரவியுள்ளது", "கடத்தியின் மையத்தில் மட்டும்", "கடத்தியின் மேற்பரப்பில் மட்டும்", "உள்ளேயும் மேற்பரப்பிலும் இரண்டிலும்"]'::jsonb,'By Gauss law, since E=0 inside, the flux through any closed surface inside is zero, meaning no net charge is enclosed. Thus excess charge can only reside on the surface. | காஸின் விதிப்படி, உள்ளே E=0 என்பதால், உள்ளே உள்ள எந்த மூடிய மேற்பரப்பின் வழியாகவும் பாயம் பூஜ்யம். எனவே மிகை மின்னேற்றம் மேற்பரப்பில் மட்டுமே இருக்க முடியும்.','TAPHY12TA02Q0324','active'),
  ('7098e4de-5c5f-574d-aa47-2c79c01b34db','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','கடத்தி முழுவதும் மின்னழுத்தம் பற்றிய உண்மையான கூற்று எது?','["மையத்திலிருந்து மேற்பரப்பிற்கு நேர்கோட்டில் மாறுகிறது", "கன அளவு முழுவதும் மற்றும் மேற்பரப்பில் மாறிலியாக உள்ளது", "மையத்தில் அதிகபட்சமாகவும் மேற்பரப்பில் பூஜ்யமாகவும் உள்ளது", "மேற்பரப்பிலிருந்து மையத்திற்கு அதிவளைவு வீழ்ச்சியாக உள்ளது"]'::jsonb,'Since E=0 inside and has no tangential component on the surface, no work is done moving a test charge within or on the surface. Hence potential is constant throughout. | உள்ளே E=0 மற்றும் மேற்பரப்பில் தொடுவான கூறு இல்லாததால், கடத்தி உள்ளே அல்லது மேற்பரப்பில் சோதனை மின்னேற்றத்தை நகர்த்துவதற்கு வேலை செய்யப்படுவதில்லை. எனவே மின்னழுத்தம் முழுவதும் மாறிலியாக இருக்கிறது.','TAPHY12TA02Q0325','active'),
  ('a47f7223-bd72-5c75-a514-2db33d1741f3','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்னேற்றம் கொண்ட கடத்தியின் மேற்பரப்பில் மின்புலம் எந்த சூத்திரத்தால் தரப்படுகிறது?','["E = σ/2ε₀", "E = σ²/ε₀", "E = σ/ε₀ n̂", "E = ε₀/σ"]'::jsonb,'Using a pill box Gaussian surface, the field just outside equals σ/ε₀ in the normal direction. The vector form is E = (σ/ε₀)n̂ where n̂ is the outward unit normal. | ஒரு மாத்திரைப் பெட்டி காஸ் மேற்பரப்பைப் பயன்படுத்தி, மேற்பரப்பிற்கு வெளியே மின்புலம் σ/ε₀ ஆகும். வெக்டர் வடிவம் E = (σ/ε₀)n̂ ஆகும், இங்கு n̂ வெளிப்புற ஒருங்கிணைந்த செங்குத்து ஆகும்.','TAPHY12TA02Q0326','active'),
  ('c84de155-2ef9-5515-a59c-94c9f85c83e2','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','குழியின் உள்ளே மின்னேற்றம் இல்லாதபோது, கடத்தியின் குழியின் உள்ளே மின்புலம் என்ன?','["வெளிப்புற மின்புலத்திற்கு சமம்", "வெளிப்புற மின்னேற்றங்கள் அல்லது மின்புலங்களைப் பொருட்படுத்தாமல் பூஜ்யம்", "குழியின் அளவுக்கு விகிதாசாரம்", "குழி சுவர்களில் அதிகபட்சம்"]'::jsonb,'Electrostatic shielding ensures that the field inside a charge-free cavity is always zero, whatever be the external field or charge configuration. This is known as Faraday cage effect. | மின்நிலைக் கவசம் என்பது குழியின் உள்ளே மின்னேற்றம் இல்லாதபோது மின்புலம் எப்போதும் பூஜ்யமாக இருக்கும் என்பதை உறுதி செய்கிறது. இது பாரடே கூண்டு விளைவு என அழைக்கப்படுகிறது.','TAPHY12TA02Q0327','active'),
  ('e83df6eb-01d5-5e51-8d9a-d099e93295ec','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','கடத்தியின் உள்ளே மின்புலம் பூஜ்யமாக இருப்பதற்கான காரணம் என்ன?','["கடத்தியில் மின்னேற்றங்கள் இல்லை", "கட்டுப்படுத்தப்படாத மின்னணுக்கள் மறுபகிர்வு செய்கின்றன", "கடத்தி முழுவதும் மின்னேற்றங்கள் நிலையாக உள்ளன", "வெளிப்புற மின்புலம் மிகவும் பலவீனமானது"]'::jsonb,'A conductor has free electrons. As long as electric field is not zero, the free charge carriers would experience force and drift. In the static situation, they redistribute until E=0 everywhere inside. | கடத்தியில் கட்டுப்படுத்தப்படாத மின்னணுக்கள் உள்ளன. மின்புலம் பூஜ்யமல்லாதவரை, இந்த கட்டுப்படுத்தப்படாத மின்னேற்ற ஊர்திகள் விசையை அனுபவித்து நகரும். நிலையான நிலையில், உள்ளே எங்கும் E=0 ஆகும் வரை அவை மறுபகிர்வு செய்கின்றன.','TAPHY12TA02Q0328','active'),
  ('948772d0-3804-52d5-80e2-4ecf0486f998','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','கடத்தியின் மேற்பரப்பில் மின்புலம் தொடுவான கூறு கொண்டிருந்தால் என்ன நடக்கும்?','["மின்னேற்றங்கள் அசையாமல் நிலைத்திருக்கும்", "மின்புலம் பூஜ்யமாகிவிடும்", "மேற்பரப்பு மின்னேற்றங்கள் விசையை அனுபவித்து நகரும்", "கடத்தியின் உள்ளே மின்புலம் அதிகரிக்கும்"]'::jsonb,'If E had a tangential component, free charges on the surface would experience force and move. In the static situation, E should have no tangential component. | E இற்கு தொடுவான கூறு இருந்தால், மேற்பரப்பில் உள்ள கட்டுப்படுத்தப்படாத மின்னேற்றங்கள் விசையை அனுபவித்து நகரும். நிலையான நிலையில், E இற்கு தொடுவான கூறு இருக்கக்கூடாது.','TAPHY12TA02Q0329','active'),
  ('aee6bfcd-6fec-51b7-8413-b6a0d4ac38d0','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','இரண்டு கொள்கலன்கள் C1 மற்றும் C2 இணை இணைப்பில் இணைக்கப்பட்டால், பயனுள்ள கொள்கலன் C என்ன?','["C = C1 × C2", "C = C1 + C2", "C = (C1 × C2)/(C1 + C2)", "C = 1/C1 + 1/C2"]'::jsonb,'When capacitors are connected in parallel, the same potential difference V is applied across each capacitor. The total charge Q is the sum of individual charges: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. Therefore, the effective capacitance is C = Q/V = C1 + C2. | இணை இணைப்பில் கொள்கலன்களுக்கு ஒரே மின்னழுத்த வேறுபாடு V பயன்படுத்தப்படுகிறது. மொத்த சார்ஜ் Q தனித்தனி சார்ஜ்களின் கூட்டுத்தொகையாகும்: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. எனவே, பயனுள்ள கொள்கலன் C = Q/V = C1 + C2 ஆகும்.','TAPHY12TA02Q0330','active'),
  ('e5bc6097-bdb4-546c-bd18-f28a59ac55d0','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','கொள்கலன்களின் இணை இணைப்பில், ஒவ்வொரு கொள்கலனுக்கும் மின்னழுத்த வேறுபாடு பற்றிய எந்த கூற்று சரியானது?','["ஒவ்வொரு கொள்கலனுக்கும் மின்னழுத்த வேறுபாடு வேறுபடும்", "அனைத்து கொள்கலன்களுக்கும் மின்னழுத்த வேறுபாடு ஒரே மாதிரியாக இருக்கும்", "மின்னழுத்த வேறுபாடு கொள்கலனுக்கு எதிர்விகிதத்தில் உள்ளது", "அனைத்து கொள்கலன்களுக்கும் மின்னழுத்த வேறுபாடு பூஜ்யமாகும்"]'::jsonb,'In a parallel combination, all capacitors are connected between the same two points, so the potential difference V across each capacitor is identical. This is a defining characteristic of parallel connection. The charges on each capacitor may differ: Q1 = C1V and Q2 = C2V. | இணை இணைப்பில், அனைத்து கொள்கலன்களும் ஒரே இரண்டு புள்ளிகளுக்கு இடையே இணைக்கப்படுவதால், ஒவ்வொரு கொள்கலனுக்கும் மின்னழுத்த வேறுபாடு V ஒரே மாதிரியாக இருக்கும். இது இணை இணைப்பின் வரையறை பண்பாகும். ஒவ்வொரு கொள்கலனின் சார்ஜ் வேறுபடலாம்: Q1 = C1V மற்றும் Q2 = C2V.','TAPHY12TA02Q0331','active'),
  ('4af05b64-d191-54f8-aaf6-c7c4053a3ac7','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','மின்னழுத்த வேறுபாடு V உடன் இணையில் உள்ள இரண்டு கொள்கலன்கள் C1 மற்றும் C2 இன் மொத்த சார்ஜ் என்ன?','["Q = C1 × C2 × V", "Q = (C1 + C2)/V", "Q = (C1 + C2)V", "Q = V/(C1 + C2)"]'::jsonb,'The total charge is the sum of charges on individual capacitors: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. Since the effective capacitance in parallel is C = C1 + C2, we can also write Q = CV. | மொத்த சார்ஜ் தனித்தனி கொள்கலன்களின் சார்ஜ்களின் கூட்டுத்தொகையாகும்: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. இணையில் பயனுள்ள கொள்கலன் C = C1 + C2 என்பதால், Q = CV என்றும் எழுதலாம்.','TAPHY12TA02Q0332','active'),
  ('10a91995-5c9d-5658-be72-1894630c7347','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',2,'C','n கொள்கலன்கள் C1, C2, ..., Cn இணை இணைப்பில் இணைக்கப்பட்டால், பயனுள்ள கொள்கலன் C இன் பொது சூத்திரம் என்ன?','["1/C = 1/C1 + 1/C2 + ... + 1/Cn", "C = C1 × C2 × ... × Cn", "C = C1 + C2 + ... + Cn", "C = (C1 + C2 + ... + Cn)/n"]'::jsonb,'For n capacitors in parallel, the effective capacitance is the algebraic sum of individual capacitances: C = C1 + C2 + ... + Cn. This is because all capacitors share the same potential difference, and charges add up. This is in contrast to series combination where reciprocals add. | n கொள்கலன்கள் இணையில் இணைக்கப்பட்டால், பயனுள்ள கொள்கலன் தனித்தனி கொள்கலன்களின் கூட்டுத்தொகையாகும்: C = C1 + C2 + ... + Cn. ஏனெனில் அனைத்து கொள்கலன்களும் ஒரே மின்னழுத்த வேறுபாட்டைப் பகிர்ந்து கொள்கின்றன, மேலும் சார்ஜ்கள் கூட்டப்படுகின்றன. இது தொடர் இணைப்பிற்கு மாறானது, அங்கு தலைகீழிகள் கூட்டப்படுகின்றன.','TAPHY12TA02Q0333','active'),
  ('3a977841-f177-5726-a2c9-6d99e222d0ec','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','உதாரணம் 2.9 இல், மூன்று 10μF கொள்கலன்கள் C1, C2, C3 தொடரில் உள்ளன, இந்த இணைப்பு C4 = 10μF உடன் இணையில் உள்ளது. வலையமைப்பின் சமான கொள்கலன் என்ன?','["10 μF", "13.3 μF", "30 μF", "3.33 μF"]'::jsonb,'First, C1, C2, C3 in series: 1/C'' = 1/10 + 1/10 + 1/10 = 3/10, so C'' = 10/3 μF. Then C'' is in parallel with C4 = 10μF: C = C'' + C4 = 10/3 + 10 = 10/3 + 30/3 = 40/3 ≈ 13.3 μF. | முதலில், C1, C2, C3 தொடரில்: 1/C'' = 1/10 + 1/10 + 1/10 = 3/10, எனவே C'' = 10/3 μF. பின்னர் C'' ஆனது C4 = 10μF உடன் இணையில் உள்ளது: C = C'' + C4 = 10/3 + 10 = 10/3 + 30/3 = 40/3 ≈ 13.3 μF.','TAPHY12TA02Q0334','active'),
  ('6e5ea5ae-18c2-585f-b1cc-8f8e356c50f3','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','500V வழங்கலுடன் உள்ள உதாரணம் 2.9 இல், கொள்கலன் C4 இன் சார்ஜ் என்ன?','["1.7 × 10^-3 C", "5.0 × 10^-3 C", "10 × 10^-3 C", "500 × 10^-3 C"]'::jsonb,'For C4 = 10μF connected directly across the 500V supply, the charge Q'' = C4 × V = 10 × 10^-6 F × 500 V = 5.0 × 10^-3 C. The charge on C1, C2, C3 (in series) is Q = C'' × V = (10/3) × 10^-6 × 500 = 1.7 × 10^-3 C. | C4 = 10μF நேரடியாக 500V வழங்கலுடன் இணைக்கப்பட்டுள்ளதால், சார்ஜ் Q'' = C4 × V = 10 × 10^-6 F × 500 V = 5.0 × 10^-3 C. C1, C2, C3 (தொடரில்) இன் சார்ஜ் Q = C'' × V = (10/3) × 10^-6 × 500 = 1.7 × 10^-3 C.','TAPHY12TA02Q0335','active'),
  ('9ba194fd-c57b-5e58-9c7b-cae50b7109ad','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','கொள்கலன்களின் இணை மற்றும் தொடர் இணைப்புகளுக்கு இடையே உள்ள வேறுபாடு பற்றிய எந்த கூற்று சரியானது?','["இணையில் சார்ஜ்கள் சமம்; தொடரில் மின்னழுத்த வேறுபாடுகள் சமம்", "இணையில் மின்னழுத்த வேறுபாடுகள் சமம்; தொடரில் சார்ஜ்கள் சமம்", "இரண்டு இணைப்புகளிலும் சார்ஜும் மின்னழுத்த வேறுபாடும் சமம்", "இரண்டு இணைப்புகளிலும் சார்ஜும் மின்னழுத்த வேறுபாடும் சமமல்ல"]'::jsonb,'In parallel combination, all capacitors have the same potential difference V across them, but charges may differ (Q1 = C1V, Q2 = C2V). In series combination, the charge on each capacitor is the same, but potential differences add up (V = V1 + V2 + ...). This is the fundamental difference between the two configurations. | இணை இணைப்பில், அனைத்து கொள்கலன்களுக்கும் ஒரே மின்னழுத்த வேறுபாடு V உள்ளது, ஆனால் சார்ஜ்கள் வேறுபடலாம் (Q1 = C1V, Q2 = C2V). தொடர் இணைப்பில், ஒவ்வொரு கொள்கலனின் சார்ஜும் ஒரே மாதிரியாக இருக்கும், ஆனால் மின்னழுத்த வேறுபாடுகள் கூட்டப்படும் (V = V1 + V2 + ...). இது இரண்டு அமைப்புகளுக்கும் இடையிலான அடிப்படை வேறுபாடாகும்.','TAPHY12TA02Q0336','active'),
  ('c1cf4b4d-f6f4-56ad-b19e-647c26b60669','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','உதாரணம் 2.9 இல், தொடரில் இணைக்கப்பட்டுள்ள C1, C2, C3 ஒவ்வொன்றின் சார்ஜ் என்ன?','["5.0 × 10^-3 C", "1.7 × 10^-3 C", "ஒவ்வொரு கொள்கலனிலும் வெவ்வேறு சார்ஜ்", "பூஜ்ய சார்ஜ்"]'::jsonb,'For capacitors in series, the charge is the same on each capacitor. The effective capacitance of C1, C2, C3 in series is C'' = 10/3 μF. With 500V supply, Q = C'' × V = (10/3) × 10^-6 × 500 = 5000/3 × 10^-6 = 1.67 × 10^-3 C ≈ 1.7 × 10^-3 C. This same charge appears on each of C1, C2, and C3. | தொடரில் உள்ள கொள்கலன்களுக்கு ஒவ்வொன்றிலும் சார்ஜ் ஒரே மாதிரியாக இருக்கும். C1, C2, C3 இன் பயனுள்ள கொள்கலன் C'' = 10/3 μF. 500V வழங்கலுடன், Q = C'' × V = (10/3) × 10^-6 × 500 = 5000/3 × 10^-6 = 1.67 × 10^-3 C ≈ 1.7 × 10^-3 C. இந்த ஒரே சார்ஜ் C1, C2, C3 ஒவ்வொன்றிலும் தோன்றும்.','TAPHY12TA02Q0337','active'),
  ('331c78f0-24c1-5367-b541-07e8ccc6e82a','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','ஒரு புள்ளி மின்னேற்றம் Q இலிருந்து தூரம் r இல் மின்னிலை V எந்த சூத்திரத்தால் கொடுக்கப்படுகிறது?','["V = Q/(4πε₀r²)", "V = Q/(4πε₀r)", "V = Qr/(4πε₀)", "V = Q/(4πε₀r³)"]'::jsonb,'The electrostatic potential due to a point charge Q at distance r is V = Q/(4πε₀r). This is derived by integrating the work done in bringing a unit positive test charge from infinity to point P against the repulsive force. The potential varies as 1/r, unlike the electric field which varies as 1/r². | புள்ளி மின்னேற்றம் Q இலிருந்து தூரம் r இல் மின்னிலை V = Q/(4πε₀r) என வழங்கப்படுகிறது. இது ஒரு அலகு நேர்மறை சோதனை மின்னேற்றத்தை எதிர்ப்பு விசைக்கு எதிராக முடிவிலியிலிருந்து P புள்ளிக்கு கொண்டுவருவதற்கான வேலையை ஒருங்கிணைப்பதன் மூலம் பெறப்படுகிறது. மின்னியல் புலம் 1/r² விகிதத்தில் மாறுவதற்கு மாறாக மின்னிலை 1/r விகிதத்தில் மாறுகிறது.','TAPHY12TA02Q0338','active'),
  ('343c466d-dade-5c00-90bd-afaeef518407','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','Q < 0 என்ற புள்ளி மின்னேற்றத்திற்கு, எந்த புள்ளியிலும் மின்னிலை V இன் குறி என்ன?','["V நேர்மறை", "V எதிர்மறை", "V பூஜ்யம்", "V தூரத்தை மட்டுமே சார்ந்தது"]'::jsonb,'For Q < 0, the potential V < 0. This means the work done by the external force per unit positive test charge in bringing it from infinity to the point is negative. Equivalently, the work done by the electrostatic force in bringing the unit positive charge from infinity to point P is positive, because for Q < 0 the force is attractive and the displacement is in the same direction as the force. | Q < 0 என்ற புள்ளி மின்னேற்றத்திற்கு, மின்னிலை V < 0. இதன் பொருள் ஒரு அலகு நேர்மறை சோதனை மின்னேற்றத்தை முடிவிலியிலிருந்து அந்தப் புள்ளிக்கு கொண்டுவருவதற்கான வெளிப்புற விசையின் வேலை எதிர்மறை. Q < 0 என்றால் விசை ஈர்ப்பு விசையாக இருப்பதால், மின்னிலைப்புற விசை செய்யும் வேலை நேர்மறை.','TAPHY12TA02Q0339','active'),
  ('831a7420-5678-57ae-937c-eb67b9671b30','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','படம் 2.4 இல், மின்னிலை V தூரம் r உடன் எவ்வாறு மாறுகிறது, மின்னியல் புலம் E உடன் ஒப்பிடும்போது?','["V 1/r² விகிதத்திலும் E 1/r விகிதத்திலும் மாறுகிறது", "V 1/r விகிதத்திலும் E 1/r² விகிதத்திலும் மாறுகிறது", "V மற்றும் E இரண்டும் 1/r விகிதத்தில் மாறுகிறது", "V மற்றும் E இரண்டும் 1/r² விகிதத்தில் மாறுகிறது"]'::jsonb,'For a point charge, the electrostatic potential V varies as 1/r (blue curve in Figure 2.4), while the electric field E varies as 1/r² (black curve). This is a fundamental difference: potential falls off more slowly with distance than the field. The potential is the integral of the field, which explains the different power laws. | புள்ளி மின்னேற்றத்திற்கு, மின்னிலை V 1/r விகிதத்தில் மாறுகிறது (நீல வளைவு), அதேசமயம் மின்னியல் புலம் E 1/r² விகிதத்தில் மாறுகிறது (கருப்பு வளைவு). இது ஒரு அடிப்படை வேறுபாடு: மின்னிலை மின்னியல் புலத்தை விட தூரத்தில் மெதுவாகக் குறைகிறது. மின்னிலை மின்னியல் புலத்தின் தொகையாக இருப்பதால் இந்த வெவ்வேறு அடுக்கு விதிகள் விளக்கப்படுகின்றன.','TAPHY12TA02Q0340','active'),
  ('2f7dd7ba-4e9c-508e-a398-08187aa24d6e','Tamil','12th','Physics','chapter2','Electrostatic Potential and Capacitance',1,'B','உதாரணம் 2.1(a) இல், 9 செ.மீ தூரத்தில் உள்ள 4×10⁻⁷ C மின்னேற்றத்தால் P புள்ளியில் மின்னிலை என்ன?','["2×10⁴ V", "4×10⁴ V", "6×10⁴ V", "8×10⁴ V"]'::jsonb,'Using V = (1/4πε₀)(Q/r) = (9×10⁹ Nm²/C²)(4×10⁻⁷ C)/(0.09 m) = 4×10⁴ V. The calculation uses Coulomb''s constant k = 1/4πε₀ = 9×10⁹ Nm²/C² and converts 9 cm to 0.09 m. | V = (1/4πε₀)(Q/r) = (9×10⁹ Nm²/C²)(4×10⁻⁷ C)/(0.09 m) = 4×10⁴ V என்ற சூத்திரத்தைப் பயன்படுத்தி கணக்கிடப்படுகிறது. கூலம்பின் மாறிலி k = 1/4πε₀ = 9×10⁹ Nm²/C² மற்றும் 9 செ.மீ = 0.09 மீ மாற்றம் பயன்படுத்தப்படுகிறது.','TAPHY12TA02Q0341','active')
INSERT INTO question_translations (id, question_id, lang_id, question_text, explanation) VALUES
  ('e0bb89ce-44e1-5575-88cc-b9f09beb69e3','34e4dfb9-1c74-54c1-957f-d67918802243',2,'மின்கடத்தாப் பொருட்களின் அடிப்படைப் பண்பு என்ன?','Dielectrics are non-conducting substances that have no or negligible number of charge carriers, unlike conductors which have free electrons. | மின்கடத்தாப் பொருட்கள் கடத்திகளைப் போலல்லாமல், இலவச மின்னேற்றம் கொண்ட துகள்களைக் கொண்டிருக்காது அல்லது மிகக் குறைந்த அளவே கொண்டிருக்கும்.'),
  ('862c8037-b081-5bed-9afa-576eff84fa25','f4e42f16-25db-578f-b6bb-1905f414a39c',2,'வெளிப்புலத்தில் வைக்கப்படும்போது, கடத்தியின் உள்ளே நிலையான நிலையில் மின்புலம் எவ்வாறு இருக்கும்?','In a conductor, free charge carriers move until the induced field exactly cancels the external field, making the net electrostatic field zero inside. | கடத்தியின் உள்ளே மின்னியல் புலம் பூஜ்யமாகிறது, ஏனெனில் இலவச மின்னேற்றத் துகள்கள் நகர்ந்து மீள்புலத்தை உருவாக்கி வெளிப்புலத்தை முற்றிலும் நீக்குகின்றன.'),
  ('1d3347c0-3339-50ad-a6ab-2c84dcf7c3fc','444385f3-a415-5377-bd05-779473fd0965',2,'மின்கடத்தாப் பொருளில் மறைவுறு புலம் வெளிப்புலத்துடன் ஒப்பிடும்போது எவ்வாறு இருக்கும்?','Unlike conductors, dielectrics cannot completely cancel the external field. The induced field only reduces the external field because free movement of charges is not possible in dielectrics. | கடத்திகளைப் போலல்லாமல், மின்கடத்தாப் பொருட்களில் மின்னேற்ற நகர்வு சாத்தியமற்றதால், மீள்புலம் வெளிப்புலத்தை முழுவதுமாக நீக்காமல் குறைக்கிறது.'),
  ('96cc2f3d-6e0b-53f4-9d1e-57eac0a49ddc','984bd096-e11f-5a38-a1c2-46add7153e7d',2,'முனைவாய் மூலக்கூறுகள் பற்றிய சரியான கூற்று எது?','In non-polar molecules, the centres of positive and negative charges coincide, so they have no permanent dipole moment. Examples include O₂ and H₂. | முனைவாய்ப் பொருட்களில் நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருப்பதால், நிரந்தர இருமுனைத் திருப்புத்திறன் இருக்காது. எடுத்துக்காட்டுகள்: O₂, H₂.'),
  ('75524224-b76b-5c20-940d-14bf206e8291','0961ad5d-45c4-5699-8b10-d4fa0e6da336',2,'பின்வருவனவற்றில் எவை முனைவாய் மூலக்கூறுகளுக்கான எடுத்துக்காட்டுகள்?','Oxygen (O₂) and hydrogen (H₂) are non-polar molecules because their symmetry causes the centres of positive and negative charges to coincide. | ஆக்ஸிஜன் (O₂) மற்றும் ஹைட்ரஜன் (H₂) முனைவாய் மூலக்கூறுகள் ஆகும், ஏனெனில் அவற்றின் சமச்சீர் காரணமாக நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருக்கும்.'),
  ('699b943e-fe3a-563c-b1ff-7f6ce89b4932','0b724734-7293-5a3a-ac8a-76e5ae26b161',2,'முனைவுறு மூலக்கூறின் சிறப்பியல்பு என்ன?','Polar molecules have permanent dipole moments because the centres of positive and negative charges are separated even without an external field. Examples include HCl and H₂O. | முனைவுறு மூலக்கூறுகளில் வெளிப்புலம் இல்லாதபோதும் நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் பிரிந்திருக்கும், எனவே நிரந்தர இருமுனைத் திருப்புத்திறன் கொண்டவை. எடுத்துக்காட்டுகள்: HCl, H₂O.'),
  ('e63a5f46-beae-5666-80a7-682f3a38a42b','f3cbc90f-dd83-5949-b126-7f40657bc26e',2,'உரையில் கொடுக்கப்பட்டுள்ள முனைவுறு மூலக்கூறுகளின் எடுத்துக்காட்டுகள் எவை?','HCl (hydrogen chloride) and H₂O (water) are examples of polar molecules because they have permanent dipole moments due to charge separation. | HCl (ஹைட்ரஜன் குளோரைடு) மற்றும் H₂O (நீர்) ஆகியவை முனைவுறு மூலக்கூறுகளுக்கான எடுத்துக்காட்டுகள், ஏனெனில் அவற்றில் மின்னேற்றப் பிரிவினையால் நிரந்தர இருமுனைத் திருப்புத்திறன் உள்ளது.'),
  ('546969b9-53c6-5474-90c2-44935b60c2d2','c8327d53-328b-595a-afa8-38acd6768c55',2,'முனைவாய் மூலக்கூறுகள் வெளிப்புலத்தில் இருமுனைத் திருப்புத்திறனை எவ்வாறு பெறுகின்றன?','In non-polar molecules, the positive and negative charges are displaced in opposite directions under an external field, creating an induced dipole moment until balanced by internal restoring forces. | முனைவாய் மூலக்கூறுகளில், வெளிப்புலத்தின் கீழ் நேர் மற்றும் எதிர் மின்னேற்றங்கள் எதிர் திசைகளில் இடப்பெயர்ச்சி அடைந்து, மீள்திருப்பு விசைகளால் சமநிலையடையும் வரை மறைவுறு இருமுனைத் திருப்புத்திறனை உருவாக்குகின்றன.'),
  ('c2f8ca98-8cc7-5392-9d5f-5ff77e3bffc5','28834f2f-c9d6-5751-b333-bb6c37441436',2,'வெளிப்புலம் இல்லாதபோது, முனைவுறு மூலக்கூறுகளின் மொத்த இருமுனைத் திருப்புத்திறன் என்ன?','Without an external field, permanent dipoles of polar molecules are randomly oriented due to thermal agitation, making the total dipole moment zero. | வெளிப்புலம் இல்லாதபோது, வெப்பச் சலனத்தால் நிரந்தர இருமுனைகள் சீரற்ற திசைகளில் அமைந்திருப்பதால், மொத்த இருமுனைத் திருப்புத்திறன் பூஜ்யமாக இருக்கும்.'),
  ('7bfcff25-a49a-5ed0-97b2-e57c17f7e728','81a69563-c645-56ef-a007-71cc943240ca',2,'மின்கடத்தாப் பொருளில் முனைவாக்கம் P என்றால் என்ன?','Polarisation P is defined as the dipole moment per unit volume. For linear isotropic dielectrics, P = χₑε₀E, where χₑ is the electric susceptibility. | மின்கடத்தாப் பொருளில் முனைவாக்கம் P என்பது அலகு பருமனுக்கான இருமுனைத் திருப்புத்திறன். நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களுக்கு P = χₑε₀E.'),
  ('21ffccae-0736-5e74-bb3d-5ea3879e7085','9677f62a-a63c-5bb1-abc2-93e8a7022e92',2,'P = χₑε₀E சமன்பாட்டில் χ₎ என்ற குறியீடு எதைக் குறிக்கிறது?','χₑ is called the electric susceptibility, a constant characteristic of the dielectric that describes how easily the material can be polarised. | χₑ என்பது மின் உணர்திறன், இது மின்கடத்தாப் பொருளின் பண்பாகும். இது அப்பொருள் எளிதாக முனைவாக்கப்படும் தன்மையைக் குறிக்கிறது.'),
  ('8155ab61-5f31-5223-aea7-5e6c01155b54','29c929de-dca5-5942-8752-ada4df3f8538',2,'நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களில் மறைவுறு இருமுனைத் திருப்புத்திறன் பற்றிய கருதுகோள் என்ன?','For linear isotropic dielectrics, the induced dipole moment is assumed to be in the direction of the field and proportional to the field strength. | நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களுக்கு, மறைவுறு இருமுனைத் திருப்புத்திறன் புலத்தின் திசையிலும் புல வலிமைக்கு நேர்விகிதத்திலும் இருக்கும்.'),
  ('d3ac9a6d-dcfe-5c46-a2b9-bcba985133ce','14109a2e-5841-50d3-9cbe-cdeacd35b2b1',2,'முனைவுறு மூலக்கூறுகளில் முனைவாக்கத்தின் அளவை எந்த இரண்டு காரணிகள் தீர்மானிக்கின்றன?','The extent of polarisation depends on the competition between dipole potential energy (which tends to align dipoles with the field) and thermal energy (which tends to disrupt alignment). | முனைவாக்கத்தின் அளவு இருமுனைத் திறன் ஆற்றல் (புலத்துடன் சீரமைக்கும்) மற்றும் வெப்ப ஆற்றல் (சீரமைப்பைக் குலைக்கும்) ஆகிய இரண்டுக்கும் இடையேயான போட்டியைப் பொறுத்தது.'),
  ('fa81a227-813f-5282-b2d6-41d508715604','0a5cdd19-f7f9-519b-afa9-c11912a1fd27',2,'உரையின் படம் 2.21-இன்படி CO₂ எவ்வாறு வகைப்படுத்தப்பட்டுள்ளது?','CO₂ is shown in Figure 2.21 as a non-polar molecule because of its linear symmetry, causing the centres of positive and negative charges to coincide. | CO₂ படம் 2.21-ல் முனைவாய் மூலக்கூறாகக் காட்டப்பட்டுள்ளது, ஏனெனில் அதன் நேர்கோட்டு சமச்சீர் காரணமாக நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருக்கும்.'),
  ('ef8c6467-ba7c-54a8-80c4-ca61c80c9036','8bd09c8b-749a-5068-991f-726c472aa0ff',2,'முனைவாக்கப்பட்ட மின்கடத்தாப் பொருளின் மேற்பரப்பில் எந்த வகை மின்னேற்றங்கள் தோன்றுகின்றன?','The collective effect of molecular dipole moments produces net charges on the surface of the dielectric. These are induced charges that are bound to the molecules, not free charges. | மூலக்கூறு இருமுனைகளின் கூட்டு விளைவாக மின்கடத்தாப் பொருளின் மேற்பரப்பில் மறைவுறு மின்னேற்றங்கள் தோன்றுகின்றன. இவை மூலக்கூறுகளில் கட்டப்பட்டவை, இலவச மின்னேற்றங்கள் அல்ல.'),
  ('87c87870-734d-572b-bb45-098c9624fc8c','465edb8f-1dab-5071-8063-63279eeaf61f',2,'வெளிப்புலம் இல்லாதபோது, வெப்பச் சலனம் முனைவுறு மூலக்கூறுகளில் என்ன விளைவை ஏற்படுத்துகிறது?','Thermal agitation causes random orientation of permanent dipoles, so the total dipole moment averages to zero when no external field is applied. | வெப்பச் சலனம் நிரந்தர இருமுனைகளை சீரற்ற திசைகளில் சுழற்றுவதால், வெளிப்புலம் இல்லாதபோது மொத்த இருமுனைத் திருப்புத்திறன் பூஜ்யமாகிறது.'),
  ('8084da85-497c-57f9-96ed-5493bd675db3','41a7bbc8-39f1-5cc5-85ad-9ae737ed46a5',2,'வெளிப்புலத்தின் கீழ் முனைவாய் மூலக்கூறில் மின்னேற்ற இடப்பெயர்ச்சி எப்போது நிற்கிறது?','The displacement stops when the external force on constituent charges is balanced by the restoring force due to internal fields in the molecule. | வெளிப்புலத்தால் ஏற்படும் விசை, மூலக்கூறின் உள் புலங்களால் ஏற்படும் மீள்திருப்பு விசையால் சமநிலையடையும்போது மின்னேற்ற இடப்பெயர்ச்சி நிற்கிறது.'),
  ('71b4e03e-4daa-53ed-a066-7f5d2087a360','367a2542-3d9f-57f9-a2f8-f2ddbbe15175',2,'நேரியல் சமச்சீர் மின்கடத்தாப் பொருட்களுக்கு, முனைவாக்கம் P, மின்புலம் E, மற்றும் மின் உணர்திறன் χₑ ஆகியவற்றை சரியாக இணைக்கும் சமன்பாடு எது?','The correct equation is P = χₑε₀E, where ε₀ is the permittivity of free space and χₑ is the electric susceptibility. | சரியான சமன்பாடு P = χₑε₀E, இதில் ε₀ வெற்றிடத்தின் மின் உடைப்புத்திறன், χₑ மின் உணர்திறன்.'),
  ('cdc67b8f-9ec2-5d32-af32-a6b362bef4b4','6db00b85-35dc-5603-aca7-e1c792dc2f90',2,'வெளிப்புலத்தில் வைக்கப்படும்போது கடத்தி மற்றும் மின்கடத்தாப் பொருளுக்கு இடையே உள்ள முக்கிய வேறுபாடு என்ன?','Conductors have free charges that move to completely cancel the external field inside. Dielectrics lack free charge carriers, so they can only reduce the field through polarisation. | கடத்திகளில் இலவச மின்னேற்றங்கள் நகர்ந்து வெளிப்புலத்தை முழுவதுமாக நீக்குகின்றன. மின்கடத்தாப் பொருட்களில் இலவச மின்னேற்றங்கள் இல்லாததால், முனைவாக்கம் மூலம் புலத்தை மட்டுமே குறைக்க முடியும்.'),
  ('c465d175-7492-55ac-bc2f-f3da9d4d16aa','a4d969f1-cce5-5e5e-9d82-7fa8ad43ba53',2,'மின்கடத்தாப் பொருளில் முனைவாக்கத்தின் அளவு பின்வருவனவற்றில் எதைப் பொறுத்தது?','The text states that the extent of the effect depends on the nature of the dielectric, which includes molecular properties like whether molecules are polar or non-polar. | மின்கடத்தாப் பொருளின் தன்மை, அதாவது மூலக்கூறுகள் முனைவுறு அல்லது முனைவாய் என்பது போன்ற பண்புகள், முனைவாக்கத்தின் அளவைத் தீர்மானிக்கின்றன.'),
  ('f8f64cb8-26b7-53f7-8809-585c9679274b','6b543a19-7a7a-5fce-8a06-6ad91fcba1a8',2,'ஒரு புள்ளி மின்னேற்றம் Q ஆதிப்புள்ளியில் வைக்கப்பட்டுள்ளது. r தூரத்தில் உள்ள P புள்ளியில் மின்னிலை V இன் வெளிப்பாடு என்ன?','The electrostatic potential due to a point charge Q at distance r is V = Q/(4πε₀r). This is derived by calculating work done in bringing a unit positive test charge from infinity to point P. | புள்ளி மின்னேற்றம் Q இன் காரணமாக r தூரத்தில் மின்னிலை V = Q/(4πε₀r) என வருகிறது. இது முடிவிலிருந்து P புள்ளிக்கு ஒரு அலகு நேர்மின்னேற்றத்தைக் கொண்டுவருவதற்கான வேலையைக் கணக்கிடுவதால் கிடைக்கிறது.'),
  ('d01e0157-60f6-5c2b-b1c4-dba262ddb7e7','6ded962d-959f-5f38-8c8d-99edda809446',2,'Q = 4 × 10⁻⁷ C என்ற புள்ளி மின்னேற்றம் 9 cm தூரத்தில் உள்ள P புள்ளியில் மின்னிலை என்ன?','Using V = (1/4πε₀)(Q/r) with Q = 4×10⁻⁷ C and r = 9×10⁻² m, we get V = 9×10⁹ × (4×10⁻⁷)/(9×10⁻²) = 4×10⁴ V. This matches Example 2.1(a). | V = (1/4πε₀)(Q/r) சூத்திரத்தைப் பயன்படுத்தி, Q = 4×10⁻⁷ C, r = 9×10⁻² m என்பதைக் கொண்டு, V = 9×10⁹ × (4×10⁻⁷)/(9×10⁻²) = 4×10⁴ V கிடைக்கிறது.'),
  ('74f6cfad-ecfa-59b3-aa52-bdba3b59dd57','d31a9e89-8f10-5fd9-8c83-474d9542f28d',2,'மின்னிலை 4 × 10⁴ V உள்ள P புள்ளிக்கு q = 2 × 10⁻⁹ C ஐ முடிவிலிருந்து கொண்டுவர செய்யப்படும் வேலை என்ன?','Work done W = qV. Substituting q = 2×10⁻⁹ C and V = 4×10⁴ V, we get W = 2×10⁻⁹ × 4×10⁴ = 8×10⁻⁵ J. This is Example 2.1(b). | செய்யப்பட்ட வேலை W = qV. q = 2×10⁻⁹ C மற்றும் V = 4×10⁴ V ஆகியவற்றைப் பதிலிட, W = 2×10⁻⁹ × 4×10⁴ = 8×10⁻⁵ J கிடைக்கிறது.'),
  ('422f0688-fc7a-5837-a7f7-982a05c1b742','83fe6775-4c51-5e41-9c13-c0ef50c8b94e',2,'எதிர்மறை புள்ளி மின்னேற்றம் Q < 0 இருக்கும்போது, எந்தவொரு புள்ளியிலும் மின்னிலை V இன் குறி என்ன?','For Q < 0, V = Q/(4πε₀r) is negative since r is always positive. Work done by external force is negative. | Q < 0 எனில், V = Q/(4πε₀r) என்பது எப்போதும் எதிர்மறையாக இருக்கும், ஏனெனில் r எப்போதும் நேர்மறை. வெளிப்புற விசையால் செய்யப்படும் வேலை எதிர்மறையாக இருக்கும்.'),
  ('e923578e-6d7a-5b34-b403-51da6c1b61ea','e1fedc89-00dc-5aa1-971f-2d9fef9bd825',2,'ஒரு புள்ளி மின்னேற்றத்தின் காரணமாக மின்னிலை தூரம் r உடன் எவ்வாறு மாறுகிறது?','V = Q/(4πε₀r) shows V ∝ 1/r. Electric field E ∝ 1/r². Figure 2.4 illustrates this. | V = Q/(4πε₀r) என்பதால், V ∝ 1/r என மாறுகிறது. மின்புலம் E ∝ 1/r² என்பதற்கு மாறாக இது உள்ளது.'),
  ('1ccde096-7b62-52aa-99fe-7d13b5dc8983','d788cada-d659-5d08-9bb8-d24ed3faa772',2,'முடிவிலிருந்து ஒரு புள்ளிக்கு மின்னேற்றத்தைக் கொண்டுவருவதற்கான வேலை பாதையைப் பொறுத்ததா?','Work done is path-independent because electrostatic force is conservative. We choose a convenient radial path for calculation. | மின்னிலைக்கு எதிராக செய்யப்படும் வேலை பாதையைப் பொறுத்தது அல்ல, ஏனெனில் மின்னச்சு விசை ஒரு பாதுகாப்பு விசை. எந்த பாதையிலும் முடிவு ஒன்றே.'),
  ('96cc3b42-c0b0-5a89-acef-641c3827dea2','60a762cd-cb8c-508c-9fbb-1d20b3909f72',2,'ஆதிப்புள்ளியிலிருந்து r'' தூரத்தில் உள்ள P'' புள்ளியில், Q மின்னேற்றத்தின் காரணமாக ஒரு அலகு நேர்மின்னேற்றத்திற்கான மின்னச்சு விசை என்ன?','By Coulomb''s law, F = (1/4πε₀)(Q/r''²) r̂, where r̂ is unit vector along OP''. This is Eq. (2.5). | Q இன் காரணமாக r'' தூரத்தில் ஒரு அலகு நேர்மின்னேற்றத்திற்கான மின்னச்சு விசை கூலம்பின் விதிப்படி F = (1/4πε₀)(Q/r''²) r̂ என அமையும்.'),
  ('668da46c-2c89-50f8-8d81-3f456e29c2ef','3c39c962-cc5d-5889-9712-dee3a9a64f4f',2,'r'' இலிருந்து r'' + Δr'' க்கு ஒரு அலகு மின்னேற்றத்தை நகர்த்துவதற்கான வேலை ΔW இன் வெளிப்பாடு என்ன?','ΔW = -(Q/4πε₀r''²) Δr''. Negative sign ensures ΔW is positive when Δr'' < 0 (moving inward). This is Eq. (2.6). | மின்னச்சு விசைக்கு எதிராக நகர்த்தும்போது செய்யப்படும் வேலை ΔW = -(Q/4πε₀r''²) Δr''. எதிர்மறைக் குறி Δr'' < 0 எனில் ΔW நேர்மறையாக இருக்க வேண்டும் என்பதற்காக.'),
  ('b8b113e3-24f0-582d-bf34-46fe5d4f01ae','afdceb8f-47b7-540c-a5eb-bead23b5f18f',2,'Q இலிருந்து r தூரத்திற்கு ஒரு அலகு மின்னேற்றத்தைக் கொண்டுவருவதற்கான மொத்த வேலையைக் கணக்கிட ஒருங்கிணைக்கும் வரம்புகள் எவை?','Integration from r'' = ∞ to r'' = r gives W = Q/(4πε₀r). This is Eq. (2.7) on the page. | r'' = ∞ இலிருந்து r'' = r வரை ஒருங்கிணைக்கப்படுகிறது. முடிவு W = Q/(4πε₀r).'),
  ('a352d095-5810-5c7b-b9ca-4f7af8272995','72babb03-630e-56e3-acb1-a594cbb2f8c4',2,'முடிவில் மின்னிலை பூஜ்யம் எனத் தேர்ந்தெடுத்தால், Q மின்னேற்றத்தின் காரணமாக P புள்ளியில் மின்னிலை என்ன?','With V(∞) = 0, potential at P equals work done by external force in bringing unit positive charge from infinity to P. This is the definition on the page. | V(∞) = 0 எனத் தேர்ந்தெடுக்கும்போது, P இல் மின்னிலை முடிவிலிருந்து P க்கு ஒரு அலகு நேர்மின்னேற்றத்தைக் கொண்டுவருவதற்கான வெளிப்புற விசையின் வேலையாகும்.'),
  ('5aab176c-7661-5d6b-a1c3-a565aa795af2','be5701ed-c54b-5d8d-a35b-d952ac03a652',2,'Q > 0 எனில், முடிவிலிருந்து P புள்ளிக்கு ஒரு அலகு நேர்மின்னேற்றத்தைக் கொண்டுவருவதற்கு விரட்டும் விசைக்கு எதிராக செய்யப்படும் வேலை:','For Q > 0, force is repulsive. Work against repulsion is positive. This positive work is stored as potential energy. | Q > 0 எனில், சோதனை மின்னேற்றத்திற்கு விரட்டும் விசை உண்டு. இந்த விரட்டலுக்கு எதிராக வேலை செய்யப்பட வேண்டும், எனவே வெளிப்புற விசையின் வேலை நேர்மறை.'),
  ('1a01757b-020d-58fc-87c8-1a005f48ca9b','1e259797-6f94-54dc-b220-ace875c2785c',2,'ஒரு புள்ளி மின்னேற்றத்தின் காரணமாக மின்புலம் E மற்றும் மின்னிலை V தூரம் r உடன் முறையே மாறுவது:','From Figure 2.4, E ∝ 1/r² (Coulomb''s law) while V ∝ 1/r. Field falls off faster than potential. | படம் 2.4 இன்படி, E ∝ 1/r² மற்றும் V ∝ 1/r. மின்புலம் தூரத்துடன் வேகமாகக் குறைகிறது.'),
  ('4532fd33-e509-5c1e-8249-bd49f037d98c','74263b0f-2bc3-589f-978e-dd5971b520c7',2,'மின்னிலையின் SI அலகு என்ன?','Potential is work per unit charge, so SI unit is Joule/Coulomb (J/C) = Volt (V). | மின்னிலை ஒரு அலகு மின்னேற்றத்திற்கான வேலை, எனவே அதன் SI அலகு Joule/Coulomb = Volt.'),
  ('40399ede-9c33-5b98-8407-9d26320b624e','f104a269-800a-5811-a20f-2963f0eaa4f4',2,'மின்புலத்தில் R இலிருந்து P க்கு q ஐ நகர்த்தும்போது நிலை ஆற்றல் வேறுபாடு எவ்வாறு கொடுக்கப்படுகிறது?','ΔU = U_P - U_R = W_RP, where W_RP is work done by external force. This is stated on the page. | நிலை ஆற்றல் வேறுபாடு ΔU = U_P - U_R = W_RP, இங்கு W_RP என்பது R இலிருந்து P க்கு q ஐ நகர்த்துவதற்கான வெளிப்புற விசையின் வேலை.'),
  ('195d4006-f691-5cc9-a6d8-3899ae493bca','d0b27c72-6ca5-5834-b109-1df9c8cd1864',2,'ஒரு புள்ளியில் மின்னேற்றத்தின் நிலை ஆற்றல் அதை எங்கிருந்து கொண்டுவருவதற்கான வேலையாக வரையறுக்கப்படுகிறது?','With potential at infinity as zero, potential energy is work done in bringing charge from infinity to that point. | முடிவில் மின்னிலை பூஜ்யம் எனத் தேர்ந்தெடுக்கும்போது, ஒரு புள்ளியில் q இன் நிலை ஆற்றல் முடிவிலிருந்து அப்புள்ளிக்கு அதைக் கொண்டுவருவதற்கான வேலை.'),
  ('87681d3e-55b5-5f54-a5d0-b46a2faec74e','6306f0f2-d685-5c62-b878-871701a074e6',2,'புள்ளி மின்னேற்றத்தின் மின்னிலையைக் கணக்கிட ஒருங்கிணைக்கும் பாதை எது?','Path-independent work allows choosing a convenient radial path from infinity to P. This simplifies calculation. | வேலை பாதையைப் பொறுத்தது அல்ல என்பதால், முடிவிலிருந்து P புள்ளிக்கு ஆர வரிசையில் ஒரு வசதியான பாதை தேர்ந்தெடுக்கப்படுகிறது.'),
  ('939aee03-3bec-5d5c-9299-ae22152fb276','7944eed7-23fb-58ba-8ed1-15190c7dd0c9',2,'ஆதிப்புள்ளியில் Q மின்னேற்றத்தின் காரணமாக r நிலை வெக்டரைக் கொண்ட P புள்ளியில் மின்னிலை எதிர்விகிதமாக உள்ளது?','V(r) = Q/(4πε₀r) shows potential is inversely proportional to distance r. | V(r) = Q/(4πε₀r) என்பதால், மின்னிலை தூரம் r உடன் எதிர்விகிதத்தில் உள்ளது.'),
  ('ae32cd93-0155-54b3-b1ae-9cd5c899d249','b1dc94d1-cce0-51d6-9db1-4269825b2362',2,'புள்ளி மின்னேற்றத்திலிருந்து தூரம் இரட்டிப்பாகும்போது மின்னிலை என்னவாகிறது?','Since V ∝ 1/r, if r doubles, V becomes half. If r → 2r, then V → V/2. | V ∝ 1/r என்பதால், r இரட்டிப்பாகும்போது V பாதியாகிறது.'),
  ('d565662f-cf56-57d4-9dcc-5bcb92b21365','c8eb3a27-79cf-54af-9d3a-cc84cb9475c6',2,'V = Q/(4πε₀r) என்ற வெளிப்பாடு எந்த எல்லை நிபந்தனையுடன் ஒத்துப்போகிறது?','As r → ∞, V → 0, consistent with choosing potential at infinity as zero. | r → ∞ எனில் V → 0, இது முடிவில் மின்னிலை பூஜ்யம் என்ற தேர்வுடன் ஒத்துப்போகிறது.'),
  ('0b6ee01f-2126-51d3-80fa-631d892f1f22','0d9a7043-c4de-50e7-8303-08af6b9c9e64',2,'நேர்மறை மின்னேற்றம் Q இன் புலத்தில் P புள்ளியில் ஓய்வில் விடப்பட்ட மின்னேற்றத்தின் நிலை ஆற்றல் என்னவாகிறது?','When external force is removed, stored potential energy provides kinetic energy. Total energy is conserved. | வெளிப்புற விசை நீக்கப்படும்போது, சேமிக்கப்பட்ட நிலை ஆற்றல் இயக்க ஆற்றலாக மாறுகிறது, மொத்த ஆற்றல் பாதுகாக்கப்படுகிறது.'),
  ('d20a6671-39db-5623-9b0d-9faa981dd6aa','5d4c138c-c69e-5410-a394-68a998998350',2,'உதாரணம் 2.1 இல் Q = 8 × 10⁻⁷ C ஆக மாற்றப்பட்டால் (தூரம் ஒன்றே), P இல் புதிய மின்னிலை என்ன?','Since V ∝ Q, doubling Q doubles potential. Original V = 4×10⁴ V, new V = 8×10⁴ V. | V ∝ Q என்பதால், Q இரட்டிப்பாகும்போது V இரட்டிப்பாகிறது.'),
  ('39c93316-c934-59b9-9793-7b7f62abd539','6523b864-c20e-5144-b7e6-207e3cb206bc',2,'மின்னிலையின் பரிமாண வாய்பாடு என்ன?','Potential = Work/Charge = [ML²T⁻²]/[AT] = [ML²T⁻³A⁻¹]. Matches dimensional table. | மின்னிலை = வேலை/மின்னேற்றம் = [ML²T⁻²]/[AT] = [ML²T⁻³A⁻¹].'),
  ('efd896b4-7102-5e54-998c-f0ea2c108b30','e2c6366c-c444-5f16-8e62-6b8786777358',2,'நேர்மறை மின்னேற்றம் Q இன் புலத்தில் எதிர்மறை மின்னேற்றம் விடப்பட்டால் அது:','Negative charge is attracted toward positive charge. Force is attractive. | எதிர்மறை மின்னேற்றம் நேர்மறை மின்னேற்றத்தை நோக்கி ஈர்க்கப்படும். இந்த ஈர்ப்பு விசையால் அது Q நோக்கி முடுக்கம் பெறும்.'),
  ('316de222-2994-50ab-ac20-796823c154b9','13198a82-e2b1-5fee-a550-d8c23b81409c',2,'மின்புலத்தில் ஒரு மின்னேற்றத்தை ஒரு புள்ளியிலிருந்து மற்றொரு புள்ளிக்கு நகர்த்துவதற்கான வேலை எதைப் பொறுத்தது?','For conservative electrostatic force, work depends only on initial and final positions, not path. | பாதுகாப்பு விசைக்கு, செய்யப்பட்ட வேலை தொடக்க மற்றும் இறுதி நிலைகளை மட்டுமே பொறுத்தது, பாதையை அல்ல.'),
  ('2279535a-0b8d-5b88-8110-8c9d68e84cd6','28fae473-824a-56bb-bb8c-66cf33a3a910',2,'ΔW = -(Q/4πε₀r''²)Δr'' வெளிப்பாட்டில் எதிர்மறைக் குறி குறிக்குவது என்ன?','Negative sign ensures ΔW is positive when Δr'' < 0 (moving inward against repulsion). | எதிர்மறைக் குறி Δr'' < 0 (உள்ளே நகரும்போது) எனில் ΔW நேர்மறை என்பதை உறுதி செய்கிறது.'),
  ('a35787a9-87e8-57d3-b193-3a9db3fefd36','0f1125f7-4591-5210-af7c-58c4bd33027a',2,'புள்ளி மின்னேற்றத்தின் காரணமாக ஒரு புள்ளியில் மின்னிலை ஒரு அடிமான அளவு, ஏனெனில்:','Potential is scalar as it represents work per unit charge. It has magnitude but no direction. | மின்னிலை ஒரு அடிமான அளவு, ஏனெனில் இது வேலை/மின்னேற்றம் என்பது அடிமான. திசை இல்லாமல் அளவு மட்டுமே உள்ளது.'),
  ('62dab5da-cb5e-5e08-ad92-e99fc9244295','1563ac5b-de0c-5aee-a09e-144597ff58e5',2,'இரண்டு எதிர் மின்னேற்றங்களை இணைக்கும் கோட்டின் செங்குத்துப் பக்கப்படுத்தியில் உள்ள எந்தவொரு புள்ளியிலும் மின்னிலை:','On the equatorial plane, potentials due to +q and -q cancel out, giving V = 0. This is a dipole property. | இரண்டு எதிர் மின்னேற்றங்களின் சமபக்கப்படுத்தியில், +q மற்றும் -q இன் மின்னிலைகள் நீக்கப்பட்டு V = 0 ஆகிறது.'),
  ('92410566-d65f-5e64-b88b-3449e932f448','c9021488-137f-5d1d-be1f-d490e816af32',2,'ஒரு புள்ளி மின்னேற்றத்திற்கு r தூரத்தில் மின்புலம் E மற்றும் மின்னிலை V இன் விகிதம் எதிர்விகிதமாக உள்ளது?','E = Q/(4πε₀r²) and V = Q/(4πε₀r), so E/V = 1/r. Thus E/V ∝ 1/r. | E = Q/(4πε₀r²) மற்றும் V = Q/(4πε₀r), எனவே E/V = 1/r.'),
  ('fff86b96-06a3-5f3c-b9bb-4ef18da2b355','018cd337-c954-556b-9aad-f2658c42f9fb',2,'இரண்டு சம நேர்மறை மின்னேற்றங்கள் ஒரு தூரத்தில் வைக்கப்பட்டால், அவற்றின் இடையே உள்ள நடுப்புள்ளியில் மின்னிலை:','By superposition, potentials add algebraically. At midpoint, each contributes equally, so total is twice one charge''s potential. | மேலடுக்கு கொள்கையால், மின்னிலைகள் கூட்டப்படுகின்றன. நடுப்புள்ளியில் ஒவ்வொரு மின்னேற்றமும் சமமாக பங்களிக்கிறது.'),
  ('0c28ca67-ee34-5718-ac08-954300c9b08a','edb53599-e6bf-5c30-8c8d-8d6f97705002',2,'இரண்டு புள்ளிகளுக்கு இடையே நிலை ஆற்றல் வேறுபாடு மட்டுமே முக்கியமானது, ஏனெனில்:','Actual potential energy is undetermined to within an additive constant. Only difference is significant as constant cancels: (U_P + α) - (U_R + α) = U_P - U_R. | நிலை ஆற்றலின் உண்மை மதிப்பு ஒரு கூட்டல் மாறிலிக்குள் உறுதியற்றது. வேறுபாடு மட்டுமே முக்கியமானது, ஏனெனில் மாறிலி நீக்கப்படுகிறது.'),
  ('79cc8202-e816-5cd8-8a3e-ea8c1c65b6be','2cc2cd6e-866c-57d9-bace-ef2270cf48c6',2,'மீத்தொகைக் கொள்கையின்படி, மின்சுமைகளின் தொகுப்பால் ஒரு புள்ளி P இல் உண்டாகும் மின்னழுத்தம் எவ்வாறு கணக்கிடப்படுகிறது?','The superposition principle states that the total potential V at point P is the algebraic sum V = V1 + V2 + ... + Vn of potentials due to each individual charge. Since potential is a scalar quantity, we add them algebraically, not vectorially. | மின்னழுத்தம் ஒரு அளவுரு (scalar) என்பதால், மீத்தொகைக் கொள்கையின்படி புள்ளி P இல் மொத்த மின்னழுத்தம் V = V1 + V2 + ... + Vn என்று தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களின் இயற்கணிதக் கூட்டுத்தொகையாகும்.'),
  ('7b18e24c-ba1e-5097-97f5-25e1a5aa8a14','952de215-13be-5d6f-9ad3-8de0c67e0ba5',2,'சீராக மின்சுமையேற்றப்பட்ட கோளப்பட்டைக்கு வெளிப்புறத்தில் (r ≥ R) மின்னழுத்தம் எதற்கு சமமாக இருக்கும்?','For a uniformly charged spherical shell, the electric field outside is the same as if all charge Q were concentrated at the center. Therefore, the potential outside is V = (1/4πε₀)(q/r), identical to a point charge at the center. | சீராக மின்சுமையேற்றப்பட்ட கோளப்பட்டைக்கு, வெளிப்புறம் மின்விசை மையத்தில் Q மின்சுமை குவித்தது போலவே உள்ளது. எனவே வெளிப்புற மின்னழுத்தம் V = (1/4πε₀)(q/r), மையத்தில் ஒரு புள்ளி மின்சுமையைப் போன்றது.'),
  ('8a605078-16b5-5f46-a09c-e9a208b4e95e','40796b2c-3a70-5913-83d2-934b81385a5a',2,'மின்சுமைகளின் தொகுப்பு q1, q2, ..., qn கொண்ட புள்ளி P இல் மின்னழுத்தம் எந்தச் சூத்திரத்தால் தரப்படுகிறது?','The potential due to a point charge is V = (1/4πε₀)(q/r). For a system of charges, by superposition, the total potential is the sum of individual potentials: V = (1/4πε₀)Σ(qᵢ/rᵢₚ). Note that potential depends on 1/r, not 1/r² (which is for electric field). | புள்ளி மின்சுமையின் மின்னழுத்தம் V = (1/4πε₀)(q/r). மின்சுமைகளின் தொகுப்புக்கு, மீத்தொகைக் கொள்கையால் V = (1/4πε₀)Σ(qᵢ/rᵢₚ). மின்னழுத்தம் 1/r இல் சாரும், 1/r² இல் அல்ல (அது மின்விசைக்கு).'),
  ('990ebb6d-77e2-577b-b501-6d8c7a7b39ab','56b9497e-2142-56c8-bdec-1f41bdb4030b',2,'கோளப்பட்டைக்குள் உள்ள மின்னழுத்தத்தின் தன்மை என்ன?','Since the electric field inside a charged spherical shell is zero (E=0), no work is done in moving a charge inside. Therefore, the potential is constant throughout the interior and equals the potential at the surface: V = (1/4πε₀)(q/R). | கோளப்பட்டைக்குள் மின்விசை சுழியம் (E=0), எனவே உள்ளே மின்சுமையை நகர்த்த எந்த வேலையும் செய்ய வேண்டியதில்லை. எனவே உள்ளக மின்னழுத்தம் மாறிலியாகவும், மேற்பரப்பு மின்னழுத்தத்திற்கு சமமாகவும் உள்ளது: V = (1/4πε₀)(q/R).'),
  ('a167cfbf-dfaa-5dab-b76c-fd8af72f737f','17a4afde-6ef4-5793-9491-b24f4fcc82b3',2,'மின்சுமை அடர்த்தி ρ(r) கொண்ட தொடர்ச்சியான மின்சுமைப் பரவலுக்கு மின்னழுத்தம் எவ்வாறு கணக்கிடப்படுகிறது?','For continuous charge distributions, we divide the distribution into small volume elements of size Δv, each carrying charge ρΔv. We calculate the potential due to each element and integrate (sum) over all contributions to get the total potential. | தொடர்ச்சியான மின்சுமைப் பரவலுக்கு, அதை Δv அளவுள்ள சிறிய கனவளவு கூறுகளாகப் பிரிக்கிறோம், ஒவ்வொன்றும் ρΔv மின்சுமையைக் கொண்டிருக்கும். ஒவ்வொரு கூறின் மின்னழுத்தத்தைக் கணக்கிட்டு, அனைத்தையும் தொகுத்து (ஒருங்கிணைத்து) மொத்த மின்னழுத்தத்தைப் பெறுகிறோம்.'),
  ('c2578126-99fd-5294-8e24-5ee17bba1408','589492e2-2ec0-5dff-b0a5-bd81c4549a1a',2,'V = (1/4πε₀)(q₁/r₁ₚ + q₂/r₂ₚ + ...) சூத்திரத்தில் r₁ₚ என்றால் என்ன?','r₁ₚ represents the distance between charge q₁ and the point P where potential is being calculated. Similarly, r₂ₚ is the distance between q₂ and P, and so on for all charges in the system. | r₁ₚ என்பது மின்சுமை q₁க்கும் மின்னழுத்தம் கணக்கிடப்படும் புள்ளி Pக்கும் இடையேயான தூரத்தைக் குறிக்கிறது. அதுபோல r₂ₚ என்பது q₂க்கும் Pக்கும் இடையேயான தூரம்.'),
  ('755d8570-80a6-57c3-a757-4d67acd3384c','e072ce03-8f15-5109-ab17-1bcb1c6d4150',2,'மின்நிலையியல் மின்னழுத்தத்திற்கு மீத்தொகைக் கொள்கை செல்லுபடியாவதற்கான காரணம் என்ன?','The superposition principle holds because electrostatic force is conservative. The work done (and hence potential) depends only on initial and final positions, not on the path. This allows us to add potentials from individual charges algebraically. | மின்நிலையியல் விசை ஒரு காப்பு விசை (conservative force) என்பதால் மீத்தொகைக் கொள்கை செல்லுபடியாகிறது. செய்யப்படும் வேலை (எனவே மின்னழுத்தம்) தொடக்க மற்றும் இறுதி நிலைகளை மட்டுமே சார்ந்தது, பாதையை அல்ல. இது தனித்தனி மின்சுமைகளின் மின்னழுத்தங்களை இயற்கணிதமாகக் கூட்ட அனுமதிக்கிறது.'),
  ('af0e5868-ec64-5403-a83b-a27328b48608','86a01b0d-3d09-52fa-9d51-553ebca9d854',2,'ஒரு கோளப்பட்டையின் மேற்பரப்பில் மின்னழுத்தம் எவ்வாறு கணக்கிடப்படுகிறது?','At the surface of a uniformly charged spherical shell (r = R), the potential is V = (1/4πε₀)(q/R). This is the same as the potential just outside, and since potential is constant inside, it is also the potential throughout the interior. | சீராக மின்சுமையேற்றப்பட்ட கோளப்பட்டையின் மேற்பரப்பில் (r = R), மின்னழுத்தம் V = (1/4πε₀)(q/R). இது வெளிப்புறத்தில் உள்ள மின்னழுத்தத்திற்கு சமம், மேலும் உள்ளக மின்னழுத்தம் மாறிலியாக இருப்பதால் இது உள்ளேயும் ஒரே மதிப்பாக இருக்கும்.'),
  ('b94b88c2-eb41-5824-a02f-45d8a798bc86','0669f9e8-2d99-53c4-b79e-118d8490abe2',2,'சமநிலை மின்னழுத்த மேற்பரப்பு B இலிருந்து A க்கு ஒரு அலகு நேர்மின் மின்னேற்றத்தை நகர்த்துவதற்கான வேலை என்ன?','The work done equals |E|dl, which also equals V - (V+dV) = -dV. All three expressions are equivalent. | | செய்யப்பட்ட வேலை |E|dl க்கு சமம், இது V - (V+dV) = -dV க்கும் சமம். மூன்று வெளிப்பாடுகளும் சமமானவை.'),
  ('94cecc38-ce0c-5254-ad17-8e6f8a371e3a','69197fc5-d54c-59d2-8b11-37d4afa798ad',2,'மின்புலம் E இன் அளவு மற்றும் செங்குத்து தூர l உடன் மின்னழுத்த V இன் மாற்ற வீதம் இடையேயான உறவு என்ன?','From the derivation, |E| = -dV/dl = +|dV|/dl. The negative sign indicates E points in direction of decreasing potential. | | வழிநடத்தலிலிருந்து, |E| = -dV/dl = +|dV|/dl. எதிர்குறி E குறைந்து வரும் மின்னழுத்தத்தின் திசையைக் குறிக்கிறது.'),
  ('511f69a8-246c-556a-9451-b674d029289c','9e063770-bedb-5b43-8284-93ffbceab051',2,'மின்புலம் எந்த திசையில் சுட்டிக்காட்டுகிறது?','Electric field is in the direction in which the potential decreases steepest. This is a key conclusion from the field-potential relation. | | மின்புலம் மின்னழுத்தம் கடுமையாகக் குறையும் திசையில் இருக்கும். இது மின்புலம்-மின்னழுத்த உறவிலிருந்து வரும் முக்கிய முடிவு.'),
  ('9530ff23-b235-51da-b4be-d3f1c93de235','5d28b6e6-a468-5ccd-97a6-b4a7a0418e50',2,'மின்புலத்தின் அளவு எதனால் கொடுக்கப்படுகிறது?','The magnitude of E is given by the change in potential per unit displacement normal to the equipotential surface. | | E இன் அளவு சமநிலை மின்னழுத்த மேற்பரப்பிற்கு செங்குத்தான அலகு இடப்பெயர்வுக்கு மின்னழுத்தத்தின் மாற்றத்தால் கொடுக்கப்படுகிறது.'),
  ('31568b5f-5eb6-539f-86f8-830f208ae6b5','44132b9d-7cbc-5c0d-8869-fac5ef6e82bb',2,'இரண்டு மின்னேற்றங்கள் q1 மற்றும் q2 இன் அமைப்பை உருவாக்கும்போது, முதல் மின்னேற்றம் q1 ஐ முடிவிலிருந்து r1 க்கு கொண்டு வருவதற்கான வேலை என்ன?','When bringing q1 first, there is no external field against which work needs to be done, so work done is zero. | | q1 ஐ முதலில் கொண்டு வரும்போது, வேலை செய்ய வேண்டிய வெளிப்புற புலம் இல்லை, எனவே செய்யப்பட்ட வேலை பூஜ்யம்.'),
  ('d7ff448a-34ff-5384-9bb5-f800a40196a8','18aadd8e-0c44-5ecd-97fd-5cf2a7d82346',2,'r12 தூரத்தில் பிரிக்கப்பட்ட இரண்டு மின்னேற்றங்கள் q1 மற்றும் q2 இன் அமைப்பின் நிலையாற்றல் என்ன?','The potential energy U = (1/4πε0)(q1q2/r12). This represents work done in assembling the configuration. | | நிலையாற்றல் U = (1/4πε0)(q1q2/r12). இது அமைப்பை உருவாக்குவதற்கான வேலையைக் குறிக்கிறது.'),
  ('0c104966-9581-59d8-9f7d-202d50ed129f','f74fd422-2ada-53e2-8496-23075e5d9d3d',2,'இரண்டு ஒத்த மின்னேற்றங்களுக்கு (இரண்டும் நேர்மறை அல்லது இரண்டும் எதிர்மறை) நிலையாற்றலின் குறி என்ன?','For like charges (q1q2 > 0), electrostatic force is repulsive and positive work is needed, so potential energy is positive. | | ஒத்த மின்னேற்றங்களுக்கு (q1q2 > 0), மின்நிலை விசை விரிவாக்கும் விசையாகும் மற்றும் நேர்மறை வேலை தேவைப்படுகிறது, எனவே நிலையாற்றல் நேர்மறை.'),
  ('7a859d4e-dc70-57c9-bfd2-5fe23418208d','74b2b2a3-f8d7-5fa0-b70f-a5d8bbaa7174',2,'இரண்டு வேறுபட்ட மின்னேற்றங்களுக்கு (ஒன்று நேர்மறை மற்றொன்று எதிர்மறை) நிலையாற்றலின் குறி என்ன?','For unlike charges (q1q2 < 0), electrostatic force is attractive and negative work is needed for reverse path, so potential energy is negative. | | வேறுபட்ட மின்னேற்றங்களுக்கு (q1q2 < 0), மின்நிலை விசை ஈர்க்கும் விசையாகும் மற்றும் தலைகீழ் பாதைக்கு எதிர்மறை வேலை தேவைப்படுகிறது, எனவே நிலையாற்றல் எதிர்மறை.'),
  ('91dbc31f-5455-5025-83d3-89af13aea2d9','647d2495-00d0-537b-8544-7d32d3da15e5',2,'மூன்று மின்னேற்றங்கள் q1, q2, மற்றும் q3 இன் அமைப்பின் நிலையாற்றல் என்ன?','The total potential energy is the sum of potential energies for each pair of charges. | | மொத்த நிலையாற்றல் ஒவ்வொரு மின்னேற்ற ஜோடிக்கான நிலையாற்றல்களின் கூடுதல்.'),
  ('8565e88f-49ee-5978-8136-0e8a7dc1f2a0','d28356d0-64a5-5588-bde8-ab9f42efc4d2',2,'மின்னேற்ற அமைப்பின் நிலையாற்றல் அமைப்பை உருவாக்க பயன்படுத்தப்பட்ட பாதையைச் சார்ந்ததா?','Because of conservative nature of electrostatic force, potential energy is independent of the path or manner of assembly. | | மின்நிலை விசையின் பாதுகாப்பு தன்மையால், நிலையாற்றல் பாதை அல்லது உருவாக்க முறை சார்ந்ததல்ல.'),
  ('4a363ec1-72c8-59dc-9910-af53dda60a82','9a04ef28-32d2-5bf0-94df-65d24ef26323',2,'மின்னேற்ற அமைப்பின் நிலையாற்றல் எதைச் சிறப்பிக்கிறது?','The potential energy is characteristic of the present state of configuration, not the way the state is achieved. | | நிலையாற்றல் தற்போதைய அமைப்பின் நிலையைச் சார்ந்தது, அந்த நிலை எவ்வாறு அடையப்பட்டது என்பதை அல்ல.'),
  ('a37c05e8-3434-5500-8150-df897ba5dddd','4ba56122-9a6a-548e-95d8-4e5517a9fe95',2,'மின்னேற்றம் q2 முதலில் கொண்டு வரப்பட்டு பின்னர் q1 கொண்டு வரப்பட்டால், நிலையாற்றல் எவ்வாறு மாறும்?','The potential energy would be the same regardless of order due to conservative nature of electrostatic force. | | மின்னேற்றங்கள் கொண்டு வரப்பட்ட வரிசையைப் பொருட்படுத்தாமல் நிலையாற்றல் ஒரே மாதிரியாக இருக்கும், மின்நிலை விசையின் பாதுகாப்பு தன்மையால்.'),
  ('df9fa9a6-c06a-5f80-8352-1f3bc49ab662','4ee6d5fe-bfa2-58c7-b3d8-a4a8a1abe478',2,'q2 ஐ முடிவிலிருந்து r2 இடத்திற்கு கொண்டு வரும்போது q1 க்குரிய மின்னழுத்தத்தின் அடிப்படையில் q2 மீது செய்யப்பட்ட வேலை என்ன?','Work done on q2 = q2 × V1(r2), where V1 is potential due to q1 at position r2. | | q2 மீது செய்யப்பட்ட வேலை = q2 × V1(r2), இங்கு V1 என்பது q1 ஆல் r2 இடத்தில் உருவாக்கப்படும் மின்னழுத்தம்.'),
  ('b19bb770-5443-5ade-b34e-f24f4a97ad53','366839b4-2866-50a8-9730-de575c76d32d',2,'U = (1/4πε0)(q1q2/r12) வெளிப்பாட்டில் U எதிர்மறையாக இருக்க என்ன நிபந்தனை?','U is negative when q1q2 < 0, which occurs when one charge is positive and other is negative. | | U எதிர்மறையாக இருக்கும் போது q1q2 < 0, இது ஒரு மின்னேற்றம் நேர்மறை மற்றொன்று எதிர்மறையாக இருக்கும் போது நிகழ்கிறது.'),
  ('f6e20d66-538e-5e12-aa33-86f4acdf22ec','4badacbe-f369-57d3-874d-50c747f0c351',2,'நிலையாற்றல் வாய்ப்பாட்டில் மாறி r12 எதைக் குறிக்கிறது?','r12 represents the distance between the two points where charges q1 and q2 are located. | | r12 என்பது மின்னேற்றங்கள் q1 மற்றும் q2 உள்ள இரண்டு புள்ளிகளுக்கு இடையேயான தூரத்தைக் குறிக்கிறது.'),
  ('fd6c3fba-aaf5-515b-8410-7728396e43b3','09ea4b58-2ecf-5b83-88dd-a814a80fe022',2,'எடுத்துக்காட்டு 2.4 இல், நான்கு மின்னூட்டங்கள் (+q, -q, +q, -q) d பக்கம் கொண்ட சதுரத்தின் மூலைகளில் வைக்கப்பட்டுள்ளன. இந்த அமைப்பை உருவாக்க தேவையான மொத்த வேலை என்ன?','The total work is calculated by bringing each charge one by one from infinity. All pair contributions are summed: adjacent pairs give -q²/(4πε₀d) and diagonal pairs give +q²/(4πε₀d√2). The final result is -q²/(4πε₀d) × (4 - √2). | மொத்த வேலை ஒவ்வொரு மின்னூட்டத்தையும் முடிவிலியிலிருந்து ஒவ்வொன்றாகக் கொண்டுவருவதன் மூலம் கணக்கிடப்படுகிறது. அருகிலுள்ள ஜோடிகள் -q²/(4πε₀d) மற்றும் மூலைவிட்ட ஜோடிகள் +q²/(4πε₀d√2) தருகின்றன. இறுதி முடிவு -q²/(4πε₀d) × (4 - √2).'),
  ('75f0c4fc-6788-525b-ba34-1a66ee15abc3','5938994e-628c-5639-8eb9-87c30727208b',2,'எடுத்துக்காட்டு 2.4 இல், நான்கு மூலை மின்னூட்டங்கள் நிலையாக வைக்கப்பட்டிருக்கும்போது, q₀ என்ற மின்னூட்டத்தை சதுரத்தின் மையம் E க்கு கொண்டுவர கூடுதல் வேலை என்ன?','The potential at center E is zero because +q charges at A and C cancel the effect of -q charges at B and D. Work done = q₀ × V = 0. | மையம் E இல் மின்னழுத்தம் பூஜ்ஜியம், ஏனெனில் A மற்றும் C இல் உள்ள +q மின்னூட்டங்கள் B மற்றும் D இல் உள்ள -q மின்னூட்டங்களின் விளைவை ரத்து செய்கின்றன. செய்யப்படும் வேலை = q₀ × V = 0.'),
  ('f9d7a611-edc4-5bb7-b075-b40d71bf0459','404b0e2b-f8e6-59e8-bed4-ebe5e0095615',2,'பிரிவு 2.8.1 இன்படி, V(r) மின்னழுத்தம் கொண்ட வெளிப்புற மின்புலத்தில் q மின்னூட்டத்தின் நிலை ஆற்றல் என்ன?','The potential energy of charge q in external field is U = qV(r). Potential is work per unit charge, so for charge q, energy is q times potential. | வெளிப்புற புலத்தில் q மின்னூட்டத்தின் நிலை ஆற்றல் U = qV(r). மின்னழுத்தம் ஒரு அலகு மின்னூட்டத்திற்கு செய்யப்படும் வேலை, எனவே q மின்னூட்டத்திற்கு ஆற்றல் q மடங்கு மின்னழுத்தம்.'),
  ('7e5711c8-27d7-5aba-92db-6ff58b69d402','3f153282-a5a7-5d69-9a27-37d889372686',2,'வெளிப்புற புலத்தில் q₁ மற்றும் q₂ என்ற இரண்டு மின்னூட்டங்கள் கொண்ட அமைப்பின் மொத்த நிலை ஆற்றல் என்ன?','Total energy has three components: energy of q₁ in external field, energy of q₂ in external field, and mutual interaction energy between the two charges. | மொத்த ஆற்றல் மூன்று கூறுகளைக் கொண்டுள்ளது: வெளிப்புற புலத்தில் q₁ இன் ஆற்றல், q₂ இன் ஆற்றல், மற்றும் இரண்டு மின்னூட்டங்களுக்கிடையேயான相互 செயல்பாட்டு ஆற்றல்.'),
  ('f1353f53-225a-5787-b8f4-f70a2822140c','eb0caf7f-4031-51ff-8be6-5df051b62791',2,'எடுத்துக்காட்டு 2.5 இல், 7μC மற்றும் -2μC மின்னூட்டங்கள் முறையே (-9cm, 0, 0) மற்றும் (9cm, 0, 0) இல் வைக்கப்பட்டுள்ளன. இந்த அமைப்பின் மின்னியக்கவியல் நிலை ஆற்றல் என்ன?','Using U = (1/4πε₀) × q₁q₂/r with the given values: U = 9×10⁹ × (7×(-2)×10⁻¹²)/0.18 = -0.7 J. The negative sign indicates attractive force. | கொடுக்கப்பட்ட மதிப்புகளுடன் U = (1/4πε₀) × q₁q₂/r சூத்திரத்தைப் பயன்படுத்தி: U = 9×10⁹ × (7×(-2)×10⁻¹²)/0.18 = -0.7 J. எதிர்குறி ஈர்ப்பு விசையைக் குறிக்கிறது.'),
  ('0813a2bf-b9c5-5ef6-a03b-29b91a7ea61b','3efe481b-acf9-592e-ac81-20a944ab7bfe',2,'எடுத்துக்காட்டு 2.5 இல் உள்ள இரண்டு மின்னூட்டங்களையும் ஒன்றிலிருந்து மற்றொன்று முடிவிலியளவு தூரத்திற்கு பிரிக்க எவ்வளவு வேலை தேவை?','Work = U_final - U_initial = 0 - (-0.7) = +0.7 J. Positive work must be done against attractive force to separate the charges to infinity. | வேலை = U_இறுதி - U_ஆரம்பம் = 0 - (-0.7) = +0.7 J. மின்னூட்டங்களை முடிவிலிக்குப் பிரிக்க ஈர்ப்பு விசைக்கு எதிராக நேர்மறை வேலை செய்யப்பட வேண்டும்.'),
  ('980de629-7d21-5c7c-bb79-4e2542814771','bdce1943-6b53-5c16-acc2-515042e32e90',2,'திசையன் p கொண்ட மின் இருமுனை, சீரான மின்புல E இல் θ கோணத்தில் வைக்கப்பட்டுள்ளது. இதன் நிலை ஆற்றல் என்ன?','The potential energy of a dipole in uniform electric field is U = -p·E = -pE cos θ. The dipole aligns with the field to minimize energy. | சீரான மின்புலத்தில் இருமுனையின் நிலை ஆற்றல் U = -p·E = -pE cos θ. ஆற்றலைக் குறைக்க இருமுனை புலத்திற்கு இணையாக சீரமையும்.'),
  ('feaf1598-4762-5938-a306-4e1e05c848d5','437c2bed-4610-5b26-bbda-e34094d8aee0',2,'நிலையான நிலையில் ஒரு கடத்தியின் உள்ளே மின்புலத்தின் மதிப்பு என்ன?','In a static situation, the electric field is zero everywhere inside a conductor. This is because free electrons redistribute themselves until the internal field cancels any external field. | நிலையான நிலையில், கடத்தி உள்ளே மின்புலம் பூஜ்யமாக இருக்கும். இது ஏனெனில் கட்டுப்படுத்தப்படாத மின்னணுக்கள் மறுபகிர்வு செய்யப்பட்டு, வெளிப்புற மின்புலத்தை நீக்கும் வரை மின்புலம் பூஜ்யமாகிறது.'),
  ('e05449da-1f89-5bfc-a96d-d6c7d0110363','872d2ede-a329-563f-a553-026bc345e7c5',2,'மின்னேற்றம் கொண்ட கடத்தியின் மேற்பரப்பில் மின்புலம் எவ்வாறு இருக்க வேண்டும்?','If the field were not normal to the surface, it would have a non-zero component along the surface. Free charges would then experience force and move, violating the static condition. | மின்புலம் மேற்பரப்பிற்கு செங்குத்தாக இல்லையெனில், மேற்பரப்பு வழியாக ஒரு பூஜ்யமற்ற கூறு இருக்கும். அப்போது கட்டுப்படுத்தப்படாத மின்னேற்றங்கள் விசையை அனுபவித்து நகரும், இது நிலையான நிலைமையை மீறுகிறது.'),
  ('cc186fde-d2c4-5d26-ab41-c43e0ebaa999','37082d9f-2c6e-5f01-b999-889a0a746967',2,'நிலையான நிலையில், மிகை மின்னேற்றம் கடத்தியில் எங்கு அமர்ந்திருக்கும்?','By Gauss law, since E=0 inside, the flux through any closed surface inside is zero, meaning no net charge is enclosed. Thus excess charge can only reside on the surface. | காஸின் விதிப்படி, உள்ளே E=0 என்பதால், உள்ளே உள்ள எந்த மூடிய மேற்பரப்பின் வழியாகவும் பாயம் பூஜ்யம். எனவே மிகை மின்னேற்றம் மேற்பரப்பில் மட்டுமே இருக்க முடியும்.'),
  ('aa4fff61-bffa-5cfc-9781-ee348b8db4aa','7098e4de-5c5f-574d-aa47-2c79c01b34db',2,'கடத்தி முழுவதும் மின்னழுத்தம் பற்றிய உண்மையான கூற்று எது?','Since E=0 inside and has no tangential component on the surface, no work is done moving a test charge within or on the surface. Hence potential is constant throughout. | உள்ளே E=0 மற்றும் மேற்பரப்பில் தொடுவான கூறு இல்லாததால், கடத்தி உள்ளே அல்லது மேற்பரப்பில் சோதனை மின்னேற்றத்தை நகர்த்துவதற்கு வேலை செய்யப்படுவதில்லை. எனவே மின்னழுத்தம் முழுவதும் மாறிலியாக இருக்கிறது.'),
  ('beb6a3fc-afed-59ec-8e28-8fc4f2dcb958','a47f7223-bd72-5c75-a514-2db33d1741f3',2,'மின்னேற்றம் கொண்ட கடத்தியின் மேற்பரப்பில் மின்புலம் எந்த சூத்திரத்தால் தரப்படுகிறது?','Using a pill box Gaussian surface, the field just outside equals σ/ε₀ in the normal direction. The vector form is E = (σ/ε₀)n̂ where n̂ is the outward unit normal. | ஒரு மாத்திரைப் பெட்டி காஸ் மேற்பரப்பைப் பயன்படுத்தி, மேற்பரப்பிற்கு வெளியே மின்புலம் σ/ε₀ ஆகும். வெக்டர் வடிவம் E = (σ/ε₀)n̂ ஆகும், இங்கு n̂ வெளிப்புற ஒருங்கிணைந்த செங்குத்து ஆகும்.'),
  ('42f37beb-ebb8-5eac-8b2f-af0b00e21ffe','c84de155-2ef9-5515-a59c-94c9f85c83e2',2,'குழியின் உள்ளே மின்னேற்றம் இல்லாதபோது, கடத்தியின் குழியின் உள்ளே மின்புலம் என்ன?','Electrostatic shielding ensures that the field inside a charge-free cavity is always zero, whatever be the external field or charge configuration. This is known as Faraday cage effect. | மின்நிலைக் கவசம் என்பது குழியின் உள்ளே மின்னேற்றம் இல்லாதபோது மின்புலம் எப்போதும் பூஜ்யமாக இருக்கும் என்பதை உறுதி செய்கிறது. இது பாரடே கூண்டு விளைவு என அழைக்கப்படுகிறது.'),
  ('d00e258b-a5f3-5d44-a70f-0831bf8af4f5','e83df6eb-01d5-5e51-8d9a-d099e93295ec',2,'கடத்தியின் உள்ளே மின்புலம் பூஜ்யமாக இருப்பதற்கான காரணம் என்ன?','A conductor has free electrons. As long as electric field is not zero, the free charge carriers would experience force and drift. In the static situation, they redistribute until E=0 everywhere inside. | கடத்தியில் கட்டுப்படுத்தப்படாத மின்னணுக்கள் உள்ளன. மின்புலம் பூஜ்யமல்லாதவரை, இந்த கட்டுப்படுத்தப்படாத மின்னேற்ற ஊர்திகள் விசையை அனுபவித்து நகரும். நிலையான நிலையில், உள்ளே எங்கும் E=0 ஆகும் வரை அவை மறுபகிர்வு செய்கின்றன.'),
  ('106a9f2a-64bc-52c1-bd9d-ddd037d8dc60','948772d0-3804-52d5-80e2-4ecf0486f998',2,'கடத்தியின் மேற்பரப்பில் மின்புலம் தொடுவான கூறு கொண்டிருந்தால் என்ன நடக்கும்?','If E had a tangential component, free charges on the surface would experience force and move. In the static situation, E should have no tangential component. | E இற்கு தொடுவான கூறு இருந்தால், மேற்பரப்பில் உள்ள கட்டுப்படுத்தப்படாத மின்னேற்றங்கள் விசையை அனுபவித்து நகரும். நிலையான நிலையில், E இற்கு தொடுவான கூறு இருக்கக்கூடாது.'),
  ('6427ee96-7409-51be-ad96-546db553cf61','aee6bfcd-6fec-51b7-8413-b6a0d4ac38d0',2,'இரண்டு கொள்கலன்கள் C1 மற்றும் C2 இணை இணைப்பில் இணைக்கப்பட்டால், பயனுள்ள கொள்கலன் C என்ன?','When capacitors are connected in parallel, the same potential difference V is applied across each capacitor. The total charge Q is the sum of individual charges: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. Therefore, the effective capacitance is C = Q/V = C1 + C2. | இணை இணைப்பில் கொள்கலன்களுக்கு ஒரே மின்னழுத்த வேறுபாடு V பயன்படுத்தப்படுகிறது. மொத்த சார்ஜ் Q தனித்தனி சார்ஜ்களின் கூட்டுத்தொகையாகும்: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. எனவே, பயனுள்ள கொள்கலன் C = Q/V = C1 + C2 ஆகும்.'),
  ('36a3547c-9b7e-58cb-90ff-3d2a21ed5629','e5bc6097-bdb4-546c-bd18-f28a59ac55d0',2,'கொள்கலன்களின் இணை இணைப்பில், ஒவ்வொரு கொள்கலனுக்கும் மின்னழுத்த வேறுபாடு பற்றிய எந்த கூற்று சரியானது?','In a parallel combination, all capacitors are connected between the same two points, so the potential difference V across each capacitor is identical. This is a defining characteristic of parallel connection. The charges on each capacitor may differ: Q1 = C1V and Q2 = C2V. | இணை இணைப்பில், அனைத்து கொள்கலன்களும் ஒரே இரண்டு புள்ளிகளுக்கு இடையே இணைக்கப்படுவதால், ஒவ்வொரு கொள்கலனுக்கும் மின்னழுத்த வேறுபாடு V ஒரே மாதிரியாக இருக்கும். இது இணை இணைப்பின் வரையறை பண்பாகும். ஒவ்வொரு கொள்கலனின் சார்ஜ் வேறுபடலாம்: Q1 = C1V மற்றும் Q2 = C2V.'),
  ('9d47eb0c-9734-51ad-9670-b23d751feb8c','4af05b64-d191-54f8-aaf6-c7c4053a3ac7',2,'மின்னழுத்த வேறுபாடு V உடன் இணையில் உள்ள இரண்டு கொள்கலன்கள் C1 மற்றும் C2 இன் மொத்த சார்ஜ் என்ன?','The total charge is the sum of charges on individual capacitors: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. Since the effective capacitance in parallel is C = C1 + C2, we can also write Q = CV. | மொத்த சார்ஜ் தனித்தனி கொள்கலன்களின் சார்ஜ்களின் கூட்டுத்தொகையாகும்: Q = Q1 + Q2 = C1V + C2V = (C1 + C2)V. இணையில் பயனுள்ள கொள்கலன் C = C1 + C2 என்பதால், Q = CV என்றும் எழுதலாம்.'),
  ('29608c7a-3489-5bcc-ab5e-b5aa3a01e76d','10a91995-5c9d-5658-be72-1894630c7347',2,'n கொள்கலன்கள் C1, C2, ..., Cn இணை இணைப்பில் இணைக்கப்பட்டால், பயனுள்ள கொள்கலன் C இன் பொது சூத்திரம் என்ன?','For n capacitors in parallel, the effective capacitance is the algebraic sum of individual capacitances: C = C1 + C2 + ... + Cn. This is because all capacitors share the same potential difference, and charges add up. This is in contrast to series combination where reciprocals add. | n கொள்கலன்கள் இணையில் இணைக்கப்பட்டால், பயனுள்ள கொள்கலன் தனித்தனி கொள்கலன்களின் கூட்டுத்தொகையாகும்: C = C1 + C2 + ... + Cn. ஏனெனில் அனைத்து கொள்கலன்களும் ஒரே மின்னழுத்த வேறுபாட்டைப் பகிர்ந்து கொள்கின்றன, மேலும் சார்ஜ்கள் கூட்டப்படுகின்றன. இது தொடர் இணைப்பிற்கு மாறானது, அங்கு தலைகீழிகள் கூட்டப்படுகின்றன.'),
  ('b3b4078b-d8a9-5285-8ce3-57917e2811d3','3a977841-f177-5726-a2c9-6d99e222d0ec',2,'உதாரணம் 2.9 இல், மூன்று 10μF கொள்கலன்கள் C1, C2, C3 தொடரில் உள்ளன, இந்த இணைப்பு C4 = 10μF உடன் இணையில் உள்ளது. வலையமைப்பின் சமான கொள்கலன் என்ன?','First, C1, C2, C3 in series: 1/C'' = 1/10 + 1/10 + 1/10 = 3/10, so C'' = 10/3 μF. Then C'' is in parallel with C4 = 10μF: C = C'' + C4 = 10/3 + 10 = 10/3 + 30/3 = 40/3 ≈ 13.3 μF. | முதலில், C1, C2, C3 தொடரில்: 1/C'' = 1/10 + 1/10 + 1/10 = 3/10, எனவே C'' = 10/3 μF. பின்னர் C'' ஆனது C4 = 10μF உடன் இணையில் உள்ளது: C = C'' + C4 = 10/3 + 10 = 10/3 + 30/3 = 40/3 ≈ 13.3 μF.'),
  ('dafb48a3-906f-57e7-afea-70759efd9464','6e5ea5ae-18c2-585f-b1cc-8f8e356c50f3',2,'500V வழங்கலுடன் உள்ள உதாரணம் 2.9 இல், கொள்கலன் C4 இன் சார்ஜ் என்ன?','For C4 = 10μF connected directly across the 500V supply, the charge Q'' = C4 × V = 10 × 10^-6 F × 500 V = 5.0 × 10^-3 C. The charge on C1, C2, C3 (in series) is Q = C'' × V = (10/3) × 10^-6 × 500 = 1.7 × 10^-3 C. | C4 = 10μF நேரடியாக 500V வழங்கலுடன் இணைக்கப்பட்டுள்ளதால், சார்ஜ் Q'' = C4 × V = 10 × 10^-6 F × 500 V = 5.0 × 10^-3 C. C1, C2, C3 (தொடரில்) இன் சார்ஜ் Q = C'' × V = (10/3) × 10^-6 × 500 = 1.7 × 10^-3 C.'),
  ('08fe6ab8-625e-5da4-8fec-0d7c8d01e9ce','9ba194fd-c57b-5e58-9c7b-cae50b7109ad',2,'கொள்கலன்களின் இணை மற்றும் தொடர் இணைப்புகளுக்கு இடையே உள்ள வேறுபாடு பற்றிய எந்த கூற்று சரியானது?','In parallel combination, all capacitors have the same potential difference V across them, but charges may differ (Q1 = C1V, Q2 = C2V). In series combination, the charge on each capacitor is the same, but potential differences add up (V = V1 + V2 + ...). This is the fundamental difference between the two configurations. | இணை இணைப்பில், அனைத்து கொள்கலன்களுக்கும் ஒரே மின்னழுத்த வேறுபாடு V உள்ளது, ஆனால் சார்ஜ்கள் வேறுபடலாம் (Q1 = C1V, Q2 = C2V). தொடர் இணைப்பில், ஒவ்வொரு கொள்கலனின் சார்ஜும் ஒரே மாதிரியாக இருக்கும், ஆனால் மின்னழுத்த வேறுபாடுகள் கூட்டப்படும் (V = V1 + V2 + ...). இது இரண்டு அமைப்புகளுக்கும் இடையிலான அடிப்படை வேறுபாடாகும்.'),
  ('024df32e-5592-501b-96a8-f72c037173de','c1cf4b4d-f6f4-56ad-b19e-647c26b60669',2,'உதாரணம் 2.9 இல், தொடரில் இணைக்கப்பட்டுள்ள C1, C2, C3 ஒவ்வொன்றின் சார்ஜ் என்ன?','For capacitors in series, the charge is the same on each capacitor. The effective capacitance of C1, C2, C3 in series is C'' = 10/3 μF. With 500V supply, Q = C'' × V = (10/3) × 10^-6 × 500 = 5000/3 × 10^-6 = 1.67 × 10^-3 C ≈ 1.7 × 10^-3 C. This same charge appears on each of C1, C2, and C3. | தொடரில் உள்ள கொள்கலன்களுக்கு ஒவ்வொன்றிலும் சார்ஜ் ஒரே மாதிரியாக இருக்கும். C1, C2, C3 இன் பயனுள்ள கொள்கலன் C'' = 10/3 μF. 500V வழங்கலுடன், Q = C'' × V = (10/3) × 10^-6 × 500 = 5000/3 × 10^-6 = 1.67 × 10^-3 C ≈ 1.7 × 10^-3 C. இந்த ஒரே சார்ஜ் C1, C2, C3 ஒவ்வொன்றிலும் தோன்றும்.'),
  ('e4dffd30-b819-5f5e-bd37-73b4c513dc3b','331c78f0-24c1-5367-b541-07e8ccc6e82a',2,'ஒரு புள்ளி மின்னேற்றம் Q இலிருந்து தூரம் r இல் மின்னிலை V எந்த சூத்திரத்தால் கொடுக்கப்படுகிறது?','The electrostatic potential due to a point charge Q at distance r is V = Q/(4πε₀r). This is derived by integrating the work done in bringing a unit positive test charge from infinity to point P against the repulsive force. The potential varies as 1/r, unlike the electric field which varies as 1/r². | புள்ளி மின்னேற்றம் Q இலிருந்து தூரம் r இல் மின்னிலை V = Q/(4πε₀r) என வழங்கப்படுகிறது. இது ஒரு அலகு நேர்மறை சோதனை மின்னேற்றத்தை எதிர்ப்பு விசைக்கு எதிராக முடிவிலியிலிருந்து P புள்ளிக்கு கொண்டுவருவதற்கான வேலையை ஒருங்கிணைப்பதன் மூலம் பெறப்படுகிறது. மின்னியல் புலம் 1/r² விகிதத்தில் மாறுவதற்கு மாறாக மின்னிலை 1/r விகிதத்தில் மாறுகிறது.'),
  ('41eb14a2-6d46-56c8-b6f3-1ea0124579a2','343c466d-dade-5c00-90bd-afaeef518407',2,'Q < 0 என்ற புள்ளி மின்னேற்றத்திற்கு, எந்த புள்ளியிலும் மின்னிலை V இன் குறி என்ன?','For Q < 0, the potential V < 0. This means the work done by the external force per unit positive test charge in bringing it from infinity to the point is negative. Equivalently, the work done by the electrostatic force in bringing the unit positive charge from infinity to point P is positive, because for Q < 0 the force is attractive and the displacement is in the same direction as the force. | Q < 0 என்ற புள்ளி மின்னேற்றத்திற்கு, மின்னிலை V < 0. இதன் பொருள் ஒரு அலகு நேர்மறை சோதனை மின்னேற்றத்தை முடிவிலியிலிருந்து அந்தப் புள்ளிக்கு கொண்டுவருவதற்கான வெளிப்புற விசையின் வேலை எதிர்மறை. Q < 0 என்றால் விசை ஈர்ப்பு விசையாக இருப்பதால், மின்னிலைப்புற விசை செய்யும் வேலை நேர்மறை.'),
  ('c14f4565-943f-53fe-9043-bb80107313b9','831a7420-5678-57ae-937c-eb67b9671b30',2,'படம் 2.4 இல், மின்னிலை V தூரம் r உடன் எவ்வாறு மாறுகிறது, மின்னியல் புலம் E உடன் ஒப்பிடும்போது?','For a point charge, the electrostatic potential V varies as 1/r (blue curve in Figure 2.4), while the electric field E varies as 1/r² (black curve). This is a fundamental difference: potential falls off more slowly with distance than the field. The potential is the integral of the field, which explains the different power laws. | புள்ளி மின்னேற்றத்திற்கு, மின்னிலை V 1/r விகிதத்தில் மாறுகிறது (நீல வளைவு), அதேசமயம் மின்னியல் புலம் E 1/r² விகிதத்தில் மாறுகிறது (கருப்பு வளைவு). இது ஒரு அடிப்படை வேறுபாடு: மின்னிலை மின்னியல் புலத்தை விட தூரத்தில் மெதுவாகக் குறைகிறது. மின்னிலை மின்னியல் புலத்தின் தொகையாக இருப்பதால் இந்த வெவ்வேறு அடுக்கு விதிகள் விளக்கப்படுகின்றன.'),
  ('9a99bae8-3de0-5704-81c8-d7a0e6f17fb7','2f7dd7ba-4e9c-508e-a398-08187aa24d6e',2,'உதாரணம் 2.1(a) இல், 9 செ.மீ தூரத்தில் உள்ள 4×10⁻⁷ C மின்னேற்றத்தால் P புள்ளியில் மின்னிலை என்ன?','Using V = (1/4πε₀)(Q/r) = (9×10⁹ Nm²/C²)(4×10⁻⁷ C)/(0.09 m) = 4×10⁴ V. The calculation uses Coulomb''s constant k = 1/4πε₀ = 9×10⁹ Nm²/C² and converts 9 cm to 0.09 m. | V = (1/4πε₀)(Q/r) = (9×10⁹ Nm²/C²)(4×10⁻⁷ C)/(0.09 m) = 4×10⁴ V என்ற சூத்திரத்தைப் பயன்படுத்தி கணக்கிடப்படுகிறது. கூலம்பின் மாறிலி k = 1/4πε₀ = 9×10⁹ Nm²/C² மற்றும் 9 செ.மீ = 0.09 மீ மாற்றம் பயன்படுத்தப்படுகிறது.')
INSERT INTO options (id, question_id, lang_id, option_key, option_text) VALUES
  ('4feb67f0-788a-55f1-8175-fd8d0c5b489e','34e4dfb9-1c74-54c1-957f-d67918802243',2,'A','கடத்திகளை விட அதிக இலவச மின்னேற்றத் துகள்களைக் கொண்டிருக்கும்'),
  ('bfecc780-8433-51ed-acb5-f8d2286e1837','34e4dfb9-1c74-54c1-957f-d67918802243',2,'B','இலவச மின்னேற்றத் துகள்களைக் கொண்டிருக்காது அல்லது மிகக் குறைந்த அளவே கொண்டிருக்கும்'),
  ('d288d5e4-7d8f-5c79-9736-2ef5ea3f49d4','34e4dfb9-1c74-54c1-957f-d67918802243',2,'C','அவற்றின் உள்ளே மின்புலம் எப்போதும் பூஜ்யமாக இருக்கும்'),
  ('1416b2c1-bc2c-5d86-83b1-de071cb85c0e','34e4dfb9-1c74-54c1-957f-d67918802243',2,'D','வெளிப்புலத்தால் முனைவாக்க முடியாது'),
  ('2e26d7bf-9c11-5c02-b8ac-6ae7927ca062','f4e42f16-25db-578f-b6bb-1905f414a39c',2,'A','வெளிப்புலத்திற்குச் சமமாக இருக்கும்'),
  ('2d9b6fa4-8ca2-58c0-ac61-6e6999e5e002','f4e42f16-25db-578f-b6bb-1905f414a39c',2,'B','வெளிப்புலத்தின் பாதியாக இருக்கும்'),
  ('5a5b8455-187b-5bdc-957e-bcfd7d4ca338','f4e42f16-25db-578f-b6bb-1905f414a39c',2,'C','பூஜ்யமாக இருக்கும்'),
  ('be57b02c-8d11-5825-b696-104331fb795b','f4e42f16-25db-578f-b6bb-1905f414a39c',2,'D','வெளிப்புலத்தின் இருமடங்காக இருக்கும்'),
  ('ce200939-ee98-5f1f-911c-c296994b52ad','444385f3-a415-5377-bd05-779473fd0965',2,'A','வெளிப்புலத்தை முற்றிலும் நீக்கும்'),
  ('bc95502e-7a34-5344-98c0-dfaa8d494a3d','444385f3-a415-5377-bd05-779473fd0965',2,'B','வெளிப்புலத்தைக் குறைக்கும் ஆனால் முற்றிலும் நீக்காது'),
  ('e6882f95-6909-5a33-9c8e-5cb7d04ab9db','444385f3-a415-5377-bd05-779473fd0965',2,'C','வெளிப்புலத்தை அதிகரிக்கும்'),
  ('dd0009ce-732e-5310-a7f0-9ffc59bdcd7d','444385f3-a415-5377-bd05-779473fd0965',2,'D','வெளிப்புலத்தில் எந்த விளைவும் ஏற்படுத்தாது'),
  ('9ddb7e14-f643-518e-af85-c0febb1f78e2','984bd096-e11f-5a38-a1c2-46add7153e7d',2,'A','அவற்றில் நிரந்தர இருமுனைத் திருப்புத்திறன் உள்ளது'),
  ('2e75d9d2-481f-53a6-8f57-245862ec3c7d','984bd096-e11f-5a38-a1c2-46add7153e7d',2,'B','நேர் மற்றும் எதிர் மின்னேற்ற மையங்கள் ஒன்றாக இருக்கும்'),
